window.MICRO={"main": {"30": [{"title": "一阕词的尾句", "body": "菊花会前，众人原只以为是饮酒。宋江兴致很好，词里先说相聚与功名，转到招安时，桌旁的动静忽然各不相同。你看见有人停箸，有人佯作没听清，有人已经等着宋江往下解释。你并不是不愿有一条正路，只是自己两次被正路尽头的人害过。若话只藏在心里，今后便更难说大家并非早就一齐应了。", "spoken": "宋江：弟兄们终要有个不负这一身本事的出路。", "choices": [{"text": "问出路是否由众人共同定", "after": "你承认事情值得商量，却不承认一位哥哥能替所有人先答应。", "trait": "trust"}, {"text": "说明自己反对受人摆布", "after": "你的异议不是嫌弃同伴，而是拒绝再将性命交给不肯担责的权势。", "trait": "freedom"}, {"text": "先听清赦罪与任用怎样安排", "after": "你将词里的盼望拆成可以逐项核对的问题。", "trait": "duty"}]}, {"title": "被听成冷心的话", "body": "你说出招安会冷了弟兄的心，席上一时静了。有人觉得你是在当众驳宋江的面子，也有人终于松一口气。你记得柴庄那一程远送，不愿把一次不同意见说成旧情全是假；可若为了报恩便不再开口，这份兄弟又反过来成了最难解的枷。你站着，必须既守住自己的判断，也让宋江听见你不是只在争谁压过谁。", "spoken": "宋江：二郎，莫不是不信我替大家想的前程？", "choices": [{"text": "明确说旧情仍在而判断不同", "after": "你不让分歧被轻易说成忘恩，也不让恩情替自己作了决定。", "trait": "oath"}, {"text": "请他允许普通军卒也说话", "after": "这个决定影响的人远比堂上几把交椅多，不该只由会作词的人讲完。", "trait": "mercy"}, {"text": "把最担心的后果逐条说出", "after": "你不以一声反对作终点，给继续商议留下了具体的题目。", "trait": "insight"}]}, {"title": "散席后的小路", "body": "鲁智深在堂外等你。他说官场里奸邪太多，不是换个称呼便能洗净。你们看法相近，却也不能只在一条小路上互相说中了。若不走招安的路，山寨怎样过冬，年老伤残者到哪里安顿，山下又如何不受军兵牵累？反对一个坏答案，比提出另一个经得起日子的答案容易。你们走得慢，第一次把留山也当作需要认真筹划的未来。", "spoken": "鲁智深：不受招安，也不能叫小的们一辈子只管逃。", "choices": [{"text": "商量守山安民的长期办法", "after": "你把拒绝变成有米有屋有退路的计划，而不是只留一句痛快。", "trait": "freedom"}, {"text": "先问伤者愿去哪里", "after": "你不替人决定何处才算有义，留下与离开都须真有选择。", "trait": "mercy"}, {"text": "约好不因堂上争执断绝来往", "after": "无论大伙后来怎样分路，旧交不必从此只剩敌我两字。", "trait": "oath"}]}], "31": [{"title": "御酒怎样分", "body": "使者带来的酒不是每个人都分得到，同一面旗底下的人忽然又被分成贵贱。平时最会说弟兄的人在这时候忙着劝忍，仿佛忍得越多便越显得前程远大。你见一个小卒看着空碗，不知该笑还是该装作全不在意。比起一场怒砸，更难的是在尚有余地的时候就问：既说一同赦罪，为何连一口酒都先叫人知道自己算不得谁？", "spoken": "军卒：头领喝便好，我们原没这个福分。", "choices": [{"text": "当众问普通军卒是否同获赦罪", "after": "你不把问题停在酒多酒少，而是问清纸上有没有这些人的名字。", "trait": "duty"}, {"text": "把自己的一份分给小卒", "after": "你不能凭一碗改尽尊卑，却先说明他不必把被轻慢当成命。", "trait": "mercy"}, {"text": "留一份酒封存，不急着饮", "after": "你不让来意不明的恩典只因摆在桌上就立刻进了人的肚子。", "trait": "insight"}]}, {"title": "纸上的轻慢", "body": "诏书展开，措辞里的蔑视比酒里更明白。你从前在县衙听见的认罪、受恩，如今换成更大的声腔。堂上有人想将每一个字都解释得好听，也有人已按不住火。你知道撕掉纸可以很快，却不能因此不再追问上头究竟答应什么、没有答应什么。你要的是往后不能再随意翻旧账的凭据，不是一张看起来令人心安的漂亮纸。", "spoken": "使者：天恩在此，尔等还要挑拣？", "choices": [{"text": "抄下赦罪的具体字句", "after": "你给这份恩典留一条日后能拿出来核对的边界。", "trait": "duty"}, {"text": "指出缺失条款，不辱骂来使", "after": "你不把一切变成谁更恭顺的争执，让问题仍落在内容上。", "trait": "restraint"}, {"text": "问能否自行退伍归籍", "after": "前程不必人人一样，想回家的人也应在这份安排里有路。", "trait": "freedom"}]}, {"title": "扯裂之后", "body": "李逵的怒吼使场面终于无法维持原先的体面。众人拦的拦、劝的劝，来使也不再肯听细话。你可以只说做得痛快，却不能不看接下来哪支队伍先受报复、哪一处村子先遭围堵。愤怒揭开了一层遮掩，若之后没有安排，最先流血的仍可能是没有参与撕诏的人。你穿过人群，想先把那些眼看就要失去秩序的地方稳住。", "spoken": "队正：弟兄都在等一句话，今夜守哪里？", "choices": [{"text": "先布置岗哨与撤离路", "after": "你把对冲突的判断落成保护，不叫守夜者只靠猜头领的心情。", "trait": "duty"}, {"text": "向普通军卒说明真实局面", "after": "你不以稳定军心为名隐去风险，让每个人至少知道为何要戒备。", "trait": "trust"}, {"text": "与鲁智深继续准备另一条出路", "after": "一张纸裂了，不必连自己想过的长远打算也一起撕掉。", "trait": "freedom"}]}], "32": [{"title": "泊边的村落", "body": "官军将到，住在泊边的村民比军卒更早着急。渔网还没收，老人走不快，牲口又不肯上船。有人催你先去列阵，说此时顾这些会误事；你却知道一面自称忠义的旗，若只在打赢以后才想起百姓，便很难说同压到门前的官军有什么区别。保人需要时间，也需要有人敢把时间从原本只属于战功的安排里分出来。", "spoken": "村人：头领，等我们把老人抬上去便好。", "choices": [{"text": "分出小队护送老弱", "after": "你没有让转移只变成一句快走，真正有人承担路上的难处。", "trait": "mercy"}, {"text": "标明军民各走哪处渡口", "after": "你减少了争船的混乱，也不让军令一来便把家口挤回险处。", "trait": "duty"}, {"text": "让村人保住能带走的粮种", "after": "你不只顾他们活过今日，也想到来年还须有饭可种。", "trait": "insight"}]}, {"title": "追击的号令", "body": "敌阵松动，前队叫着追。你看见一段好夺的路，也看见身后队形已被水沟分成两截。若只按最响的声势往前，快的人会更快，慢的人却可能在看不见时被切断。你从前习惯一人斗几个人，如今得学着让没有自己本事的人也能活过同一场胜仗。你举起手，不是为了叫所有人都看你敢冲多远，而是要他们知道何时该停。", "spoken": "队正：再赶一段，功劳就是咱们的！", "choices": [{"text": "等后队齐整再推进", "after": "你放过了看似容易的一点军功，保住队伍不因胜心而散。", "trait": "duty"}, {"text": "护住弃械者，不纵兵伤人", "after": "你不将敌我之外的退路全堵死，仍肯为停手划出一个条件。", "trait": "mercy"}, {"text": "自己去确认粮道尚通", "after": "你把胜负背后最容易被忘记的地方重新看了一遍。", "trait": "insight"}]}, {"title": "缴来的东西", "body": "战后摆在地上的不只有兵器，也有钱袋、衣物与写着姓名的家书。有人说敌兵的东西自然都归赢的人，另有人已把百姓失散的包裹也混了进来。最难查的不是大家都看见的一次抢夺，而是热闹散去以后，每个人觉得顺手拿一点不算什么。你若只查一个最没靠山的小卒，规矩又会变成只会往下落的东西。", "spoken": "军卒：头领，如何分才算服气？", "choices": [{"text": "先分清军械与民物", "after": "你不让一句缴获抹掉物件真正的主人。", "trait": "insight"}, {"text": "头领的随从也一同受查", "after": "规矩能查到熟人，众人才知道这回不只是在找个替罪的。", "trait": "duty"}, {"text": "将能认主的家书与私物留出", "after": "即使对方败了，他也不必连一封回家的话都被当作战利品。", "trait": "mercy"}]}], "33": [{"title": "一百零八人之外", "body": "堂上的名字人人记得，步军里的小卒却常只按队、按数报来。你翻一张伤病簿，发现有人被漏了，因为最初登记的人觉得他只是替别人扛过一段粮。可这人同样在军中受伤，也同样有家。你知道若今天不肯为这样一行小字较真，明日再说所有弟兄都在册便只能算对着自己说好听话。", "spoken": "书手：不是故意不写，只怕名单越添越没完。", "choices": [{"text": "按人重核，不只按队数", "after": "你愿意为一个没有名号的人多花时间，册子才开始接近真实的队伍。", "trait": "duty"}, {"text": "找同乡补上姓名与家口", "after": "他不再只是伤卒一名，将来有人知道该将消息送到哪里。", "trait": "mercy"}, {"text": "请不同山头互相对验", "after": "你不让谁因不在熟人眼前就最容易被漏掉。", "trait": "insight"}]}, {"title": "两册不能相同的事", "body": "一册用来报功，另一册用来安置。有人建议省事，直接照抄；你却看见报功册上最醒目的事，未必是生活里最急的事。一个杀敌多的人不一定没有余粮，一个无功可报的人也不该因此在失去双腿后无人问。若两册永远一样，帮助便只能跟在已经多得的人身后，永远轮不到只盼活下去的那一边。", "spoken": "书手：头领要另列，便须逐个再问一遍。", "choices": [{"text": "把伤病与家口单列", "after": "你让安置有自己的道理，不只成为军功赏赐的尾巴。", "trait": "mercy"}, {"text": "留副本交各队保管", "after": "每个人离营以后，仍能找到不只存于一座衙门里的凭据。", "trait": "duty"}, {"text": "向部下解释为何再问", "after": "你不让查验变成另一轮叫人害怕的审问，众人更肯讲实话。", "trait": "trust"}]}, {"title": "写到自己这一行", "body": "轮到武松的名字时，书手只写了头领与武艺，问你家口便想留空。你说有哥哥，又想到每一次写下地址都可能让旁人顺着找到他。人在册里需要被看见，家人又未必愿被权势随时看见。你不能把这种两难交给一个会写字的人随便处理；该公开多少、由谁保管，也都是守护承诺的一部分。", "spoken": "书手：二郎只说记在哪里，我照办。", "choices": [{"text": "将家口联络与公册分存", "after": "你留下安置所需的消息，也没有将所有私处一并摊在堂前。", "trait": "insight"}, {"text": "指定可靠之人知晓后路", "after": "你不再像昔日押送前那样，将能否报信全交给偶然。", "trait": "oath"}, {"text": "给普通军卒同样的选择", "after": "你不把只有头领才配保留余地当成理所当然。", "trait": "mercy"}]}], "34": [{"title": "分金的喧闹", "body": "梁山分金大买市，银钱与旧物各有去向。有人兴奋地打算未来穿什么官衣，也有人只是默默将一小袋钱收进包袱。你不想泼所有人的兴，却也不能假装看不见这些不同的期待。离开山寨以后，谁还能说不，谁又会因为已经受赏而再无退路？你问了几个人，才发现想过这个问题的远不只你自己。", "spoken": "一个老卒：有了路费，我只想回去看看娘。", "choices": [{"text": "将想退伍的人另记下", "after": "你不让他们的愿望被更响的报国与封赏淹没。", "trait": "freedom"}, {"text": "提醒众人留好归籍凭据", "after": "钱花完会少，凭据丢了却可能连回家也被人拦住。", "trait": "duty"}, {"text": "替老卒寻一个同行的同乡", "after": "归途不仅要有钱，也要有人能在半路认得你、帮你一把。", "trait": "mercy"}]}, {"title": "旧寨的最后一巡", "body": "你绕到寨门时，守门的人问往后这里会留给谁。前几日大家还在争座次，今日却得认真想空下来的屋与仓如何处置。山下几户受过战火的人想借住，喽啰担心会被说成私相授受。你可以一走了之，可这些房屋曾替你挡过风，也曾耗过山民的粮。离开若只带走金银而不清旧账，所谓功成便又像只由有本事的人收场。", "spoken": "守门人：二郎，这些钥匙交到谁手里？", "choices": [{"text": "把余粮与住处公开点清", "after": "你不让离寨后的第一件事就是又一场无人负责的争夺。", "trait": "duty"}, {"text": "给无家者暂居的办法", "after": "你为旧寨找一个还能护人的去处，而不只留一片空壳。", "trait": "mercy"}, {"text": "同鲁智深核实留山的退路", "after": "不论最后去留，另一条路至少不是酒后的一句空话。", "trait": "freedom"}]}, {"title": "要不要一同走", "body": "宋江来问你的打算，没有旁人时，他显得比堂上疲倦。你知道他并非只为自己求官，也真想替弟兄洗去贼名；同样真实的是，他很难承认自己的办法不能适合所有人。你想起最初那场远送，这回却不能再让一句兄弟便代替自己的回答。去与留都得讲清缘由，才不至于许多年后又说当初只是跟着走了。", "spoken": "宋江：二郎，你若肯同去，我心里便踏实些。", "choices": [{"text": "说明同去仍要保留自己的判断", "after": "你愿意照看朋友，却不把将来的异议一并提前交出。", "trait": "oath"}, {"text": "请他尊重不愿再受招安的人", "after": "你将一条退路讲到当事人面前，不只留给私下议论。", "trait": "freedom"}, {"text": "把伤卒安置作为同行的条件", "after": "情分不只在一句肯去，也在肯不肯为更弱的人争一个安排。", "trait": "duty"}]}], "35": [{"title": "军令的另一张脸", "body": "队伍进入官军地界后，称呼变了，规矩也更密。山上争执尚能叫同伴劝开，这里一纸军令落下，便可能再无回话的时辰。你并不反对纪律，只担心它又成为只会压到小卒头上的东西。你看见自己的部下努力学着新礼数，像怕一个动作不对就被人重新叫作贼。你得使他们知道，站得齐不等于必须把人也站没了。", "spoken": "队正：新令下来，该怎样传给小的们？", "choices": [{"text": "把令文逐条说明而非只催照办", "after": "你愿意让人理解自己承担什么，不只学会在喝令时低头。", "trait": "duty"}, {"text": "明确辱骂不属于军令", "after": "你不因已经换了旗号，就默认普通军卒理当受尽轻慢。", "trait": "mercy"}, {"text": "保留本队原有的接应办法", "after": "新旧之间有变，患难时能找到彼此的联系不能轻易断。", "trait": "oath"}]}, {"title": "陈桥驿的空位", "body": "一场冲突以后，小卒被斩的消息传来。营里议论很多，最后却都被一句军法压低。你望着他原先睡的那处，觉得空出来的位置比一份再响的胜报都具体。若只用更猛烈的操练压住心痛，队伍会更会忍，却未必更知道怎样避免下一次。你必须承认自己没能救下已经发生的事，也仍有责任护住后来的人。", "spoken": "军卒：是不是我们怎样做，都只配先领罪？", "choices": [{"text": "查清经过，改掉诱发冲突的安排", "after": "你不让一条人命只换来几日气愤，至少让下一次不再照旧发生。", "trait": "duty"}, {"text": "替死者核对家乡与亲属", "after": "他的名字不是一个已结案的小卒，而是一户人家再等不到的人。", "trait": "mercy"}, {"text": "允许同袍说出难过与不服", "after": "你不拿稳定队伍作由头，逼他们把所有话都闷在心里。", "trait": "trust"}]}, {"title": "谁替他传消息", "body": "报死讯比报捷难得多。书手想用同一式公文发走，省事也不必触及太多痛处。你读完，却觉得那纸上仿佛从未住过一个会吃饭、会害怕、会想家的活人。你也知道不能把自己的愤恨写成新的谣言，让家属在伤心之外还背上一份不实。真正的交代需要事实、抚恤与一个肯将他们的话再带回来的人。", "spoken": "书手：若家里追问，可教谁回话？", "choices": [{"text": "指定一名认得死者的人送信", "after": "你让亲属能问见过他的人，而不只收到一张已经无人愿谈的纸。", "trait": "mercy"}, {"text": "将能兑现的抚恤写明", "after": "悲悯不只是一声叹息，期限、数目与经办者都须可以追问。", "trait": "duty"}, {"text": "不许随意编作战死邀功", "after": "你不让一个已经无法自辩的人，死后还替众人的体面继续受用。", "trait": "restraint"}]}], "0": [{"title": "客馆里的冷炭", "body": "你第一次出现在这座庄院时，已经寄居许久。疟疾一阵冷、一阵热，桌边的饭菜凉了，门外的人却仍有工夫说你酒后打人的旧事。你不是没有受过好饭好酒，只是后来每一次失控都被人记住。现在想叫一声添炭，也得先想着会不会又落下一句闲话。廊下传来脚步，你必须决定怎样度过这个不体面的早晨。", "spoken": "庄客：大官人有客，暂且顾不上这头。", "choices": [{"text": "客气请他添些炭", "after": "你把话说得平稳。庄客不再绷着脸，答应饭后替你捎一篮干炭。", "trait": "trust"}, {"text": "自行去廊下向火", "after": "你披衣出去，不愿再求人；起身太急，寒意在骨缝里又翻了一回。", "trait": "skill"}, {"text": "认下从前醉后失礼", "after": "庄客没料到你会提这件事，迟疑片刻，将原本要拿走的热水留下。", "trait": "restraint"}]}, {"title": "火锨柄一响", "body": "廊下火盆旁，你把身子蜷得比平常小。一个过路客人不慎踩动火锨，炭火和冷灰腾起来，你被惊得跳起，怒话几乎先于看清来人脱口而出。柴进赶到，叫了一声宋押司。那人没有摆架子，也没有先问你在庄里是什么身份，而是认真向你赔礼。这一下，你既惊于他的姓名，也窘于自己方才的模样。", "spoken": "宋江：是宋江失了脚，惊着足下。", "choices": [{"text": "先收拳，再通姓名", "after": "你压住已经举起的手，清清楚楚报出自己是清河武松。", "trait": "restraint"}, {"text": "问他可是及时雨宋江", "after": "那人点头，你终于把传闻里的名字与眼前这张风尘满面的脸对上。", "trait": "trust"}, {"text": "坦白自己正犯寒病", "after": "你没有再拿怒气遮掩虚弱。宋江请人挪来坐具，让你先坐下说。", "trait": "insight"}]}, {"title": "席间第三位", "body": "柴进重新整治杯盘，宋清也来相见。你本想坐到最下首，宋江却一再相让。人们看着一条大汉为一张椅子推辞，只有你知道，这与刚才那盆冷炭有什么分别。席间说到你因酒后争执逃来清河以外，又听闻旧日对手已经救活；回乡终于不必只像一个畏罪逃走的人。宋江问起家中，你第一次把哥哥的炊饼担讲得那么详细。", "spoken": "宋江：既然挂念兄长，总该带封信、留个消息。", "choices": [{"text": "把哥哥的住处说给他听", "after": "你为自己留下一处可以托信的人情，也不再只用拳脚介绍自己。", "trait": "trust"}, {"text": "承认醉酒曾坏了自己的事", "after": "这句话说出口比敬酒难，却使你以后更容易分清勇气与失控。", "trait": "restraint"}, {"text": "向宋清打听归途", "after": "宋清摊开沿路见闻，你记住渡口、客舍与哪些地方可以投宿。", "trait": "insight"}]}], "1": [{"title": "送得太远的人", "body": "离庄的日子，宋江回房取了盘费，又坚持同宋清送你出门。你们走过五七里，话并不总是江湖大事；有时只是哪里饭香、哪里路窄。你几次停住请他们回去，宋江却说前头还有小店。你本来将这一场相逢当作寄人篱下的一点暖意，直到对方真的陪你走得如此远，才知道有人会把客中一句兄弟认真到底。", "spoken": "宋江：再送几步，吃三盅便作别。", "choices": [{"text": "在酒店正式拜为义兄", "after": "你把一场偶遇变成了约定，知道日后无论赞同与否，都不能轻看这份相识。", "trait": "trust"}, {"text": "谢他，不再因盘费推让争执", "after": "你收下十两赠银，也记住受恩并不意味着把往后的判断一同交出去。", "trait": "insight"}, {"text": "叮嘱他在柴庄好生安歇", "after": "你不只说自己会回报，也开始挂念这个正因官司奔走的客人。", "trait": "mercy"}]}, {"title": "路上的一封旧信", "body": "分别后，你又走了几日。客舍里的灯油要钱，热水要等，行脚人一句路况也未必可靠。你想给哥哥写信，却不知道他是不是仍住在清河县。柜上有人说阳谷县生意好，许多小贩都迁了过去。这个消息让归途不再只是一条熟路：你得先寻人。包袱里盘缠尚足，可每一文都要从眼前的舒坦与往后的余地之间分开。", "spoken": "客舍掌柜：寻人要问做同样买卖的，比问门牌快。", "choices": [{"text": "向沿街饼贩打听", "after": "你记下几个名字，归乡开始有了具体线索，而不只是一股急切。", "trait": "insight"}, {"text": "省下酒钱，请人代写寻亲信", "after": "纸上没有豪言，只有武二还在、正在回来的几句实话。", "trait": "restraint"}, {"text": "替同行老人背过一段包袱", "after": "老人讲起前头县镇的路，你得了一份不必用钱换来的可靠消息。", "trait": "mercy"}]}, {"title": "一碟肉与三只碗", "body": "晌午进了酒店，店主人先摆三只碗。你还没有出名，也没有任何人知道这顿酒以后会被多少人讲起；眼下只是肚饿、脚酸，觉得酒香得很。第一碗入口辛烈，第二碗觉得身上暖起来，第三碗落下时，店家便停手了。你把他的规矩当作卖弄，店家却看着日头，像在计算另一个你尚未放在心上的时辰。", "spoken": "店家：酒卖得出去，客人的性命也得顾。", "choices": [{"text": "先问这规矩从何而来", "after": "你听出店家真正担心的是过冈时辰，不是怕你少给酒钱。", "trait": "insight"}, {"text": "先吃饱再饮", "after": "你把碗推开片刻，让饥饿不再替酒意作主。", "trait": "restraint"}, {"text": "付清酒肉钱再议", "after": "你不让争执变成赖账的误会，也给这场对话留下了讲理的余地。", "trait": "trust"}]}], "2": [{"title": "关门以前", "body": "酒家收起外头的小桌，过路人也开始找住处。你站在门槛上看天，还明亮得很；一个猎户却说，山里的亮与山下不是一回事。猎户的裤脚有新泥，腰边绳索磨得发亮，正是这些不起眼的痕迹让提醒多了分量。你若把所有劝阻都当成看轻自己，便永远只能用冒险来证明别人错了。", "spoken": "猎户：我们进去找过，虎不是只守在一棵树下。", "choices": [{"text": "问清他们搜山的路线", "after": "你记下草深处与水沟，遇险时便不至于被地形逼住。", "trait": "insight"}, {"text": "承认自己没走过如今的山路", "after": "承认不熟悉并没有折损本事，反让猎户愿意把话讲完。", "trait": "restraint"}, {"text": "请他转告店家别替你担责", "after": "你不肯让自己的选择成为别人日后受罚的缘由。", "trait": "mercy"}]}, {"title": "山脚的人家", "body": "离开酒店不远，你见路旁有家人的院门拿粗木顶着。一个妇人隔门提醒你别再往前，她家柴担已经许多天不敢上山。虎害并不是榜上一个威风的名字，它会让炉里没有干柴，让卖柴的人失去饭钱。你以前想到猛兽，想到的是能不能打；如今在这道紧闭的门前，你得看见打赢或打不赢之外还有谁在受苦。", "spoken": "门里的人：壮士若回来，替我们捎句话也好。", "choices": [{"text": "记下这户人家的名字", "after": "你知道自己若真能除患，功劳不能只留在县衙的赏榜上。", "trait": "mercy"}, {"text": "借一根结实短绳备用", "after": "妇人从门缝递出绳子，你答应不论用不用得上都回头还来。", "trait": "trust"}, {"text": "查看山脚退路", "after": "你先记住能退往哪里，才把身子转向山中。", "trait": "insight"}]}, {"title": "红印里的真话", "body": "破庙墙上贴着官司榜文，印泥被雨水洇开了一角，禁行的时辰仍看得清楚。你不是突然少了胆，只是再不能说店家编了故事。折回去会不会被笑？这个念头甚至比虎更快地钻出来。你把手放在哨棒上，发现此刻真正要压服的，是心里那点宁可冒险也不肯认错的硬气。", "spoken": "心声：山不会因为我不信，就变得容易走。", "choices": [{"text": "把榜上的时辰读清", "after": "你终于将提醒当作信息，而不再当作一句要赢过的激将。", "trait": "insight"}, {"text": "承认害怕，却不乱走", "after": "惧意使你看得更细，不必非要装作什么都不怕。", "trait": "restraint"}, {"text": "折一枝松枝标出回路", "after": "若后头还有人来，这处标记至少能让他多想一想。", "trait": "mercy"}]}], "3": [{"title": "一根棒的分量", "body": "上坡后，酒劲没有完全散，石头却越来越滑。哨棒从掌心传来木纹，你试着换了几次握法，想起从前与人交手时怎样追一步、退半步。与人比武尚能听见骂声，林中的东西不会给你报姓名。风刚停，你便意识到自己已经走进一个声音格外少的地方，连虫鸣都像被什么压住。", "spoken": "心声：手里有棒，不等于处处都有落棒的空当。", "choices": [{"text": "先看脚下可转身的地方", "after": "你把最有把握的一击留给真正能站稳的时候。", "trait": "skill"}, {"text": "放轻步子听林中动静", "after": "你听清了枝条折动的方向，没有把每一阵风都当成虎。", "trait": "insight"}, {"text": "松开肩背，缓一口气", "after": "你没有凭空多出气力，只是不再提前把它耗尽。", "trait": "restraint"}]}, {"title": "黄风先到", "body": "腥风从林间压过来，虎影还没完全显出，你先看见落叶朝同一个方向卷起。那东西比人想象中大，也比画上的虎更近。你来不及想打虎以后会如何，只来得及选第一步落在哪块石头上。多退一步可能撞树，早出一棒可能把自己送进爪下。先前肯不肯听劝，如今都化作身体里有没有留住一点清醒。", "spoken": "交锋：先让最凶的一扑落空，才谈得上回手。", "choices": [{"text": "看准落爪处再侧身", "after": "你没有向后直退，给虎扑过之后留下了转身的机会。", "trait": "skill"}, {"text": "盯住虎肩，不看自己的棒", "after": "眼睛终于没有被手里那点依靠拴住，你捕到了真正的发力方向。", "trait": "insight"}, {"text": "忍住抢先一击", "after": "你让最急的一口气留在胸里，等它扑空。", "trait": "restraint"}]}, {"title": "折断的依靠", "body": "哨棒劈在枯树上，裂声比虎吼还叫人心里一空。你手中只剩半截木，山里却没有可以再买一根棒的地方。你看见虎调过头来，明白从前以为可靠的东西会在一瞬间失去；接下来能不能活，要看你肯不肯立即换一种做法，而不是为刚才那一击恼怒。", "spoken": "心声：棒断了，脚和眼还在。", "choices": [{"text": "丢开断棒，空出双手", "after": "你不再让一件已经坏掉的东西占住活下去所需的动作。", "trait": "skill"}, {"text": "借树干遮住半边身位", "after": "你用地形补上手里失去的距离，逼它不能从两边同时扑来。", "trait": "insight"}, {"text": "把惊惶压进下一次呼吸", "after": "你能听见自己的心跳，却没有任它催乱脚步。", "trait": "restraint"}]}], "4": [{"title": "响声过后", "body": "虎不再扑来时，你的腿才开始发软。刚才拼命时没有察觉的痛，一处处从手背、肩头、腰间浮出来。你想立刻下山，脚下却像陷着泥。树影再一晃，你竟以为还有一只虎。打赢并不会使惧意自动消失；你必须学会分清什么是真正的新危险，什么只是身体还没从险境里回来。", "spoken": "心声：活下来了，也得一步步走回人间。", "choices": [{"text": "先寻稳处坐下", "after": "你不再用硬撑证明胜负，等能站稳时才重新起身。", "trait": "restraint"}, {"text": "检查周围有没有第二道虎迹", "after": "你把疑心变成查看，而不是在惊惧中盲走。", "trait": "insight"}, {"text": "朝山下呼喊求助", "after": "承认自己需要帮手，让你第一次在这场胜仗后感到不再孤身。", "trait": "trust"}]}, {"title": "猎户的火把", "body": "火把从树后亮起时，几名猎户先举起了器械。他们以为又要看见被虎害的人，却见你坐在路边，断棒丢在脚旁。有人想上前，有人仍不敢靠近。你才明白一个人刚从险处走出来，身上也可能带着叫旁人害怕的样子。你需要的不只是说服他们虎死了，还要让他们知道你不是另一个来山上逞凶的人。", "spoken": "猎户：壮士，真个是你一个打的？", "choices": [{"text": "先放下手中残木", "after": "他们看见你的手是空的，才敢近前查看虎与伤。", "trait": "restraint"}, {"text": "请他们同去确认", "after": "你让每个人都亲眼看清，不必只凭你一人口说。", "trait": "insight"}, {"text": "问他们有没有因此受罚", "after": "有人讲起官司限期，你从那语气里听见了许久压着的委屈。", "trait": "mercy"}]}, {"title": "抬虎的杠子", "body": "众人商议怎样把虎抬下山。你想帮忙抬杠，肩一抬却险些跌倒，猎户赶紧扶住。有人笑你方才那般勇猛，此刻却连半副担子也扛不起；笑声没有恶意，反倒让你终于松下来。村里孩子还在远处等消息，山脚那户人家的柴也该能重新担出去。原来一场胜利真正落地，是这些寻常事又能继续。", "spoken": "猎户：走前头慢些便好，这一程让我们来。", "choices": [{"text": "将那根借来的绳交还", "after": "你没有因为立了大功就忘记先前很小的一句承诺。", "trait": "trust"}, {"text": "替猎户扶住不稳的一端", "after": "你只做自己此刻做得到的事，不再把帮忙变成又一次逞强。", "trait": "mercy"}, {"text": "听他们讲山上旧路", "after": "陌生的山渐渐有了人名与地名，不再只剩一个打虎的故事。", "trait": "insight"}]}], "5": [{"title": "看热闹的人群", "body": "消息进城，比你本人走得还快。街道两侧挤满了人，夸赞一声接一声。你听得高兴，也觉得有些陌生：他们看见的是能够打虎的壮士，并不知道你前几日在客馆里连热水都得等人脸色。一个街坊问你是否从来不怕，你想起破庙前的榜文，知道若顺着这句话答下去，自己以后便会被困在别人盼望的样子里。", "spoken": "街坊：如此英雄，还有什么怕的！", "choices": [{"text": "说起猎户与店家的提醒", "after": "你让热闹里也有那些没上山打虎、却认真替人担心的姓名。", "trait": "mercy"}, {"text": "承认自己也曾犹疑", "after": "人群一静，随即有人笑着点头；你不必靠无所畏惧才能站在这里。", "trait": "restraint"}, {"text": "把除患经过讲清", "after": "你分清亲眼见到的事与运气，没有替自己添出第二只虎。", "trait": "insight"}]}, {"title": "银盘前的旧账", "body": "县衙摆出赏银，县令说你替本县除了大害。猎户站在一旁，手上的茧与鞭责留下的痕迹都比银盘更叫你在意。你可以把全部赏银收下，没有谁能说不该；也可以拿它换一份人心。不过一时分银并不等于以后就再无虎害，若官府只在出事时催责，却不肯提前听山民说话，故事还会换一个山头重来。", "spoken": "县令：壮士可有什么话要说？", "choices": [{"text": "替猎户请求免去旧责", "after": "你没有只把银钱看作恩赏，也把它当作替受苦的人开口的机会。", "trait": "mercy"}, {"text": "问清都头的日常职责", "after": "你想知道接下的是什么差事，不只知道会得到什么名声。", "trait": "insight"}, {"text": "先留够自己治伤的费用", "after": "你承认活着并好好走下去，本就是这份赏银该有的用处。", "trait": "restraint"}]}, {"title": "一条新腰带", "body": "衙吏送来腰带与差役要用的物件，告诉你哪条街归谁巡，遇到哪几家豪强最好少管闲事。你刚要穿上能保护人的衣服，便先听见它有哪些地方不能走。你想到哥哥若也在这县城卖饼，会不会同样被人劝着忍一忍。这条腰带的分量原来不在金属铜扣，而在往后你愿意为了谁停下脚。", "spoken": "老衙役：做得长久，得懂得留情面。", "choices": [{"text": "把街巷与人名记在心里", "after": "你先弄明白哪些人有处诉说、哪些人只能受着，再决定怎样办差。", "trait": "insight"}, {"text": "说明欺人的事总要问", "after": "老衙役叹气，却也知道你不是只来穿一身体面的新衣。", "trait": "mercy"}, {"text": "请老衙役教你办差手续", "after": "你不只求拳头管用，也想学会让一句公道留下凭据。", "trait": "trust"}]}], "6": [{"title": "担子的另一头", "body": "巡街时你听见身后有人喊二哥。那声音比一街的称赞都熟悉，转身却见哥哥吃力地把担子放下。他先看你身上的新衣，手在旧围裙上擦了又擦，仿佛怕把一身官差衣服弄脏。你恍惚想起幼时他也是这样把好的一块饼先让给你；只是这些年你一直在外，他的担子却没有轻过。", "spoken": "武大：我道你回来也得先去旧县，没想到就在这里。", "choices": [{"text": "替他接过肩上的担", "after": "你这一身力气终于不必用来打倒谁，只需让哥哥肩头轻一点。", "trait": "mercy"}, {"text": "先向街坊介绍这是家兄", "after": "哥哥站直了些；人们知道这位小贩不只有一根没人帮扶的担子。", "trait": "trust"}, {"text": "问清他每日走哪几条街", "after": "你开始认识哥哥真实的日子，而不是只想着拿些银钱给他。", "trait": "insight"}]}, {"title": "半块留下的饼", "body": "哥哥领你回家，先把一只篮子收进灶边。你伸手掀开，看见几块卖相不好的饼，他说这是自己留来吃的。赚头薄，完整的都要留给客人。你想起自己在路上嫌过的饭，也想起柴庄里因一碗酒与人发怒。哥哥没有责怪，只将新出笼最软的一只塞到你手里。你若只说以后都由你养着，未必听得见他在这些日子里怎样活下来。", "spoken": "武大：做得惯了，不辛苦。你先吃热的。", "choices": [{"text": "陪他把今日账算完", "after": "你知道了一担饼值多少工夫，也不再轻易拿一句不辛苦替他作答。", "trait": "insight"}, {"text": "告诉他不必把好的都让你", "after": "哥哥起初还推，你将饼掰开，两个人各吃了半块。", "trait": "mercy"}, {"text": "留够修蒸笼的钱", "after": "你先补上眼前会坏的物件，让关心能落到第二天早晨。", "trait": "trust"}]}, {"title": "家中的新位置", "body": "屋里多了一位嫂嫂，你不能像过去那样把包袱随处一丢。哥哥忙着介绍，潘金莲也张罗碗筷，笑声里各自都有一点不习惯。你想留下多住些日子，又不愿让哥哥左右为难。门外差役来问晚上是否回衙舍；这不过一句寻常问话，却逼着你想清楚，回到家乡以后，亲近与分寸要怎样一并守住。", "spoken": "潘金莲：叔叔如今做了都头，住处可不能太寒酸。", "choices": [{"text": "让哥哥先定家里规矩", "after": "你不因自己的身份更体面，就越过这个家的主人替所有人作主。", "trait": "trust"}, {"text": "先住衙舍，照常回来吃饭", "after": "你给彼此留了舒展的地方，也保留了日日相见的约定。", "trait": "restraint"}, {"text": "问嫂嫂有什么需要帮忙", "after": "你尽了亲属之礼，却不把客气误认作更近的关系。", "trait": "insight"}]}], "7": [{"title": "递来的酒盏", "body": "哥哥下楼张罗买卖，楼上只剩你与潘金莲。她递来酒，说的却不是家常。你起初想用一句玩笑带过，又怕沉默被当作默许。窗外还有卖货声，屋里却仿佛忽然离街道很远。你在柴庄见过受恩后的为难，此处更不能把不愿得罪人当作不说清楚的理由。那只酒盏仍停在半空，等着你接。", "spoken": "潘金莲：叔叔怎地总这样拘谨？", "choices": [{"text": "不接酒，明说应守叔嫂分际", "after": "话说得清楚，不必靠暧昧的笑替双方留下误会。", "trait": "restraint"}, {"text": "推说有公差，立即下楼", "after": "你先离开不合适的独处，再找有哥哥在的时候讲明往来。", "trait": "insight"}, {"text": "换一只空碗，等哥哥回来", "after": "你没有让这杯酒继续下去，也不以侮辱的话激化眼前的局面。", "trait": "mercy"}]}, {"title": "哥哥听不懂的话", "body": "你寻了个只有兄弟二人的空当，想叮嘱哥哥早些收摊。哥哥以为你担心他身子，笑说自己还挑得动。话到这里，最容易变成一番不许这样、不许那样的命令；可是哥哥并不是你的部下，也不能靠被关在家里就免去别人作恶。你得把能防的危险与他讲明，又不能让他觉得自己连维持生计的本事也被弟弟看轻。", "spoken": "武大：我若不出门，哪来的钱过日子？", "choices": [{"text": "商量早收摊而非全不出门", "after": "你们约定一个能做到的时辰，担忧终于变成可以执行的小事。", "trait": "trust"}, {"text": "把近来不安说给他听", "after": "哥哥渐渐收起笑，你不再假定一句暗示就能让他明白所有意思。", "trait": "insight"}, {"text": "请他有事便去衙门找你", "after": "你告诉他这不是给你添麻烦，是兄弟之间本就该有的依靠。", "trait": "mercy"}]}, {"title": "门闩不是答案", "body": "临走时，你把门闩试了两遍，潘金莲在旁看着，脸色不快。你知道严密的门能挡住外头的人，却挡不住屋里人的决定。哥哥夹在中间，忙着说大家都为家好。若你只以怒意收场，他以后遇到难堪的事反而可能不敢告诉你。你站在门边，须在维护界限与保住兄弟愿意说话之间找出一条路。", "spoken": "武大：二哥，你有话慢慢说，我听着。", "choices": [{"text": "同哥哥约好报信的办法", "after": "你把事情落在谁去找谁、何时该开口，而不是只留一道禁止。", "trait": "insight"}, {"text": "收住火气，重申会来探望", "after": "哥哥记住的是你仍会回来，不是自己又挨了弟弟一场训。", "trait": "mercy"}, {"text": "不再单独登楼，与街坊往来", "after": "你用自己的行动守住分际，让旁人也看得明白。", "trait": "restraint"}]}], "8": [{"title": "东京公差", "body": "县令唤你入内，说有财物需要押往东京。你才在阳谷找到容身之处，偏偏这时又要走远。公差的日期写在簿上，哥哥的事却没有哪位衙吏替你记着。你问能否多留一天，对方说车夫已经雇好。你不能把私人忧虑全变成县衙的麻烦，也不能因为有张公文，就假装家里那些不安已经自行消失。", "spoken": "衙吏：来回几月，只要路上不生事。", "choices": [{"text": "核对行程，算清何时能回", "after": "你给家中留下的是可估计的归期，不是一句含糊的很快回来。", "trait": "insight"}, {"text": "请同僚在你不在时多照应街口", "after": "你把人情用在一个具体的地方，也愿意日后替对方担一回差。", "trait": "trust"}, {"text": "先将哥哥用得上的钱单放一袋", "after": "你没有把全部盘缠带在身上，家中的日用终于也有了余地。", "trait": "mercy"}]}, {"title": "寻一个会留心的人", "body": "郓哥常在附近卖果子，知道谁家开门早、谁家忽然几天没出摊。你买了几个果子，没有立刻把钱塞过去叫他替你看人，而是先问他近来生意。他不过是个要挣生活的年轻人，不该因为替都头跑一趟就卷入危险。你需要他的眼睛，也得说清一旦有事，不许他逞强去拦那些惹不起的人。", "spoken": "郓哥：真有不对，我去哪里报信？", "choices": [{"text": "写下沿路可转信的客舍", "after": "你让报信有了去处，不必指望消息自己飞到千里之外。", "trait": "insight"}, {"text": "告诉他先顾自己安全", "after": "你要的是一声及时的提醒，不是另一个人替你冒险。", "trait": "mercy"}, {"text": "答应不论什么消息都不迁怒", "after": "郓哥终于肯直视你，不必担心说真话先惹恼了官差。", "trait": "trust"}]}, {"title": "哥哥送到街口", "body": "出门那天，哥哥把饼装得太满，包袱比来时沉了许多。你说路上买得到，他却还是又塞一只。走到街口时，兄弟都不愿先说分别。你忽然明白，远行的人只需面对前路，留在家里的人却要每天猜测那个人究竟走到了哪里。你可以留下一个临时安排，也可以认真把这次离开当作需要众人共同照应的事。", "spoken": "武大：你办差归办差，莫又为争一口气打人。", "choices": [{"text": "答应到了客舍便传信", "after": "你让哥哥有个可以等来的消息，不必只对着日头数天。", "trait": "trust"}, {"text": "记下他今日这句劝", "after": "你被说得有些窘，却知道这句话比路上多少祝你扬名的话都重。", "trait": "restraint"}, {"text": "先安排好街坊照应再上路", "after": "你花去一点出发前的工夫，可能换回往后无法重来的机会。", "trait": "insight"}]}], "9": [{"title": "归途的坏预感", "body": "东京的差事总算办完，归途却比去时更叫人心急。城门外几个熟面孔看见你，笑意一闪便收了回去；有人想说什么，又被旁人扯住。你不能凭脸色就认定出了事，也不能为了不听坏消息而先大声说笑。街上卖饼的担子没有出现，屋檐下也没闻见惯有的蒸汽。你开始顺着这些空缺，一项项找回这段你不在场的日子。", "spoken": "街坊：武都头，你先进去坐，有话慢慢听。", "choices": [{"text": "请最早知情的人从头说起", "after": "你没有让自己的猜测先盖住实情，日期与来往的人逐渐清楚。", "trait": "insight"}, {"text": "先问哥哥现在何处", "after": "你将最要紧的事放在前头，没有被流言牵着去追旁人的姓名。", "trait": "mercy"}, {"text": "收起官差的威势再开口", "after": "街坊看见你愿意听，才敢讲那些自己也拿不准的细节。", "trait": "trust"}]}, {"title": "卖果人的顾虑", "body": "郓哥避开街口的人，低声叫住你。他记得有人怎样威胁自己，也记得你临走前说过有事要报。事情越严重，一个没什么家底的人越容易成为最先被舍掉的那个。他把果篮换到另一只手上，眼睛始终看着退路。你若只催他说，他也许会开口，却未必敢把最重要的那一段讲完。", "spoken": "郓哥：我说了，你可得护住我家里人。", "choices": [{"text": "先安排他家暂避", "after": "你先兑现保护，再听他作证，信任不必靠催逼得来。", "trait": "mercy"}, {"text": "请他只讲亲眼所见", "after": "你把猜测与见闻分开，免得日后一句不实便拖倒全部证言。", "trait": "insight"}, {"text": "让他知道可以分几次说", "after": "你给了害怕的人喘息的余地，反而听见了更完整的经过。", "trait": "trust"}]}, {"title": "谁动过那只碗", "body": "屋中的东西已经被收拾过一回。桌角有不一样的水痕，药罐换过位置，连惯用的碗也有人说找不见了。你未必懂得所有药性，却知道有人急着改变一间屋子的原貌时，便不能只听他解释得多顺。你想起办差核对封缄的规矩：是谁接手，何时移走，又有谁看见。寻亲的急切，正在被迫变成一件件细小的查验。", "spoken": "邻舍：那碗我见过，后来是谁收走的，我却没看清。", "choices": [{"text": "将物件与证言分别记下", "after": "你不急着替物证定名，先保住它们以后可以互相印证的位置。", "trait": "insight"}, {"text": "请无涉邻舍一起见证", "after": "这不再只是你一人的记忆，日后谁也不能轻易说是武二自己摆的。", "trait": "trust"}, {"text": "不责怪没看清的邻舍", "after": "你不拿旁人的无能为力出气，仍有人愿意继续帮你找。", "trait": "mercy"}]}], "10": [{"title": "何九叔的门", "body": "何九叔迟迟不开门。你站在外头，能听见里面急促的脚步和压低的争执。他不是没有看见异样，只是看见以后还得活在这县里。你的名声能叫人一时不敢欺负他，却不能时时守在他门前。你若真要这人作证，便不能把他怕事简单骂作没良心，更不能把自己的急当作他必须立刻冒死的道理。", "spoken": "何九叔：武都头，我也有一家老小。", "choices": [{"text": "先说明证人怎样受护", "after": "你把谁来接应、材料留在哪里说清，他终于松开门闩。", "trait": "mercy"}, {"text": "请他写下最少而确定的所见", "after": "你不逼他替所有疑处作答，只保住他确实知道的那部分。", "trait": "insight"}, {"text": "留出不当众开口的办法", "after": "何九叔可以先密写一份，胆怯不再意味着所有真相都得沉下去。", "trait": "trust"}]}, {"title": "两份供状", "body": "写供状的人落笔很快，问起如何断句却又怕得罪谁。你的话愤怒时容易一长串，读回去却未必分得清哪件事是哪天。你逼自己放慢，把人名、日期、所见与推断一条条拆开。写成一份不难，难的是即使这份进了衙门，外头仍要有人知道上面究竟写了什么。你从前只知拳头不能被夺，现在才知纸也会无声无息地失踪。", "spoken": "代书人：若只留这一张，交上去便不在你手里了。", "choices": [{"text": "誊一份交可信之人保管", "after": "原件进门以后，真相仍有另一处可以找到。", "trait": "insight"}, {"text": "请证人逐条核对再按记", "after": "他们确认的是自己说过的话，而不是被迫替你的怒火担保。", "trait": "trust"}, {"text": "删去未经证实的指控", "after": "你宁肯让纸上少一句痛快，也不让对方抓住一处空话推翻全部。", "trait": "restraint"}]}, {"title": "衙门台阶", "body": "你在这阶下受过夸奖，如今站回来，差役却不肯像从前那样直视你。说是知县忙，说是等传，说是家事莫闹，话换了几种，意思始终没有动。你已经准备了证言，却还得面对一个更难的事实：有人不是没听懂，而是不愿让听懂以后该做的事落到自己头上。你需要决定怎样让这次拒绝本身也不能被抹掉。", "spoken": "衙吏：你若识相，先回去，莫坏了体面。", "choices": [{"text": "请他说明不受理的缘由", "after": "你让模糊的推托变成可以再次追问的话，而不只是一道关门声。", "trait": "insight"}, {"text": "护送证人先离开围观处", "after": "你不让街上的议论替仇人指出最容易报复的是谁。", "trait": "mercy"}, {"text": "克制住当场动手的冲动", "after": "你把能留下证据的一刻保住，没有让一拳头先把诉状变成闹堂。", "trait": "restraint"}]}], "11": [{"title": "街坊的席位", "body": "你把知情者请来，屋里每张凳子都坐得比往日拘束。人们未必不辨是非，只是害怕这一席酒以后，县里还容不容得他们做买卖。你不能把所有旁观者都当作仇人；也不能再让真正的主谋躲在人情与面子后头。一场清算要站得住，除了你敢出手，还得让真话能在旁人心里留下不被恐吓冲散的位置。", "spoken": "街坊：二郎，你须让我们听个明白。", "choices": [{"text": "请证人各讲各的经过", "after": "你没有替他们编成一套齐整的话，差异反倒让经过更可信。", "trait": "insight"}, {"text": "说明不追究无涉的人", "after": "席间的人终于敢呼吸，知道自己不是被叫来替你认下一场私仇。", "trait": "mercy"}, {"text": "先收好能带走的书证", "after": "即使今晚以后你得离开，仍有人可以说明这里发生了什么。", "trait": "restraint"}]}, {"title": "报仇以后还有谁", "body": "你想到的不是一场只在自己眼中痛快的胜负。哥哥的旧相识还要住在阳谷，郓哥仍要卖果，何九叔一家仍得开门。仇人一倒，并不代表他们身后的势力也立刻散去。若你此刻只顾把刀磨得锋利，明日最弱的人可能先替你付账。你在昏暗的灯下，把那些需要先安顿的人名一遍遍念过，发现这一页竟比仇人的名单还长。", "spoken": "心声：我不能讨到一份公道，却留下更多人受害。", "choices": [{"text": "给证人安排退路", "after": "你把愤怒换成盘缠、住处与接应，活人的名字没有被报仇压住。", "trait": "mercy"}, {"text": "请可靠街坊共同照应", "after": "你知道自己未必还能留在县里，于是把保护变成不只靠一人的事。", "trait": "trust"}, {"text": "把事情始末再写一遍", "after": "你给日后留下一份不必由胜者替你讲述的经过。", "trait": "insight"}]}, {"title": "决定要背的名字", "body": "夜深后，你解下腰带，放在桌边。武都头这个称呼才得来不久，却已经不能替你解决最想解决的事。你也想过从此不认任何规矩，但那样一来，谁又能区分你与借权势欺人的人？你可以自己担下自己做过的事，不让弱者替你顶罪；这未必能使结局容易，却能决定往后每一次想起这一天时，你究竟还能不能看着自己的眼睛。", "spoken": "心声：该由武二领的，我自己去领。", "choices": [{"text": "说清罪责由自己承担", "after": "你没有让帮忙的人因为一句义气就被拖进同样的牢门。", "trait": "mercy"}, {"text": "留下一封给旧友的信", "after": "你不求对方替你遮掩，只求还有人知道你为何走到这里。", "trait": "trust"}, {"text": "把随身银钱分作安置与路费", "after": "复仇过后的路也得有人走，你终于开始替那条路准备。", "trait": "restraint"}]}], "24": [{"title": "庵门外的声音", "body": "蜈蚣岭的山道上，一间庵堂本该能让行脚人歇脚，门里传出的声音却不似诵经。你如今也披僧衣，反而更知道衣冠不能替人担保。若只因自己是逃亡之人便绕开，那里头求救的人便再少一个可能；若不辨情形贸然冲入，也可能先惊着最该保护的人。你伏在门侧听了一会，先找那声音究竟从哪一处传来。", "spoken": "门内有人低声求救，随后又竭力止住。", "choices": [{"text": "看清可让人避走的出口", "after": "你先替被困者找路，不把营救只想成打一场赢得漂亮的架。", "trait": "mercy"}, {"text": "绕至窗边辨认人数", "after": "你将威胁与无涉的人分开，决定动手时不再只凭一个影子。", "trait": "insight"}, {"text": "压住喝骂，先发出安全的招呼", "after": "门里的人知道来者肯听，不必在第二场惊吓中先替谁挡刀。", "trait": "restraint"}]}, {"title": "不肯让路的道人", "body": "道人看见你的刀，先用自己修行的身份压人，再问你何寺何庵。他似乎以为只要把谈话变成僧道间的面子，屋里那个人便可以继续不说话。你太熟悉这种做法：县衙说家事，张府说受恩，如今又有人说门规。名号可以不同，被遮住的总是那个无权替自己解释的人。", "spoken": "道人：这庵里的事，岂轮得到过客多问？", "choices": [{"text": "请屋里的人自己说话", "after": "你不与他比谁的名号更大，先让被他代言的人有一次开口。", "trait": "mercy"}, {"text": "站住出口，不受话头牵引", "after": "你让他无法趁争辩把人带走，话里的破绽渐渐显出。", "trait": "skill"}, {"text": "指出自己只问是否自愿留此", "after": "你把纷乱名目收回一个具体问题，不让其借题转开。", "trait": "insight"}]}, {"title": "救出以后", "body": "女子走出庵门时仍不敢离你太近。你知道一个刚从恶处逃出来的人，不会因为救她的是好汉便立刻信任另一把刀。她说得出家乡，却记不清绕山的路径。你不能把人救出门便算一件善事办完，还得让她有地方落脚、有办法回去；同时也得承认她有权选择不与你同行。", "spoken": "女子：恩公只指一条有人家的路，便够了。", "choices": [{"text": "请邻近人家接应归途", "after": "你把帮助交到能让她安心的人手里，不迫她继续依附自己。", "trait": "mercy"}, {"text": "留下路费，尊重她自行去留", "after": "你没有把救命之恩变成要求对方听从的债。", "trait": "restraint"}, {"text": "问清还有没有别的被困者", "after": "你不因已经救到一个人便匆匆离开，对周遭又查了一遍。", "trait": "insight"}]}], "25": [{"title": "不该再饮的一杯", "body": "到了孔家庄附近，你又累又饿，酒家一句不肯添酒很快点燃了旧火。你已经换了行者衣，身上的习气却没有因此一并改掉。眼前人不知你的来历，你也未必认得这地方谁与谁相熟。一个小争执若只为证明谁更不肯服软，转眼便会使你刚避过的官司添出新的仇家。", "spoken": "店家：不是不做你生意，须等主人回来。", "choices": [{"text": "先听清拒绝的缘由", "after": "你给对方说完一句话的机会，也给自己一个不必立即动拳的停顿。", "trait": "insight"}, {"text": "吃些饭再作决定", "after": "你认出饥饿与疲乏正在放大怒意，没有让它们替你认人。", "trait": "restraint"}, {"text": "另问一处可以买食的地方", "after": "离开争执不等于败了，你也不必让所有路都变成擂台。", "trait": "freedom"}]}, {"title": "醒在绳索旁", "body": "醒来时，身边的情形已不由你作主。你想不起自己最后怎样倒下，只看见庄客将绳索收得很紧。别人说你仗势闹店，你却也记得自己确实先动了怒。你并不因承认这一点就该受任何羞辱，但若连一点错都不肯认，眼前所有人便更难相信你不是还要再闹一场。", "spoken": "孔亮：你这汉子，还认得昨夜的事么？", "choices": [{"text": "先承认自己酒后失分寸", "after": "你没有拿英雄名声抹去做错的部分，对话因此能往下讲。", "trait": "restraint"}, {"text": "问有无人因争执受伤", "after": "你先顾到自己的行为可能留下什么后果，而不只问绳索何时解。", "trait": "mercy"}, {"text": "把真实来历简明说出", "after": "你不再靠更响的骂声挣回面子，给人一个可以查明误会的机会。", "trait": "insight"}]}, {"title": "宋江又在席间", "body": "宋江的声音出现时，你先松一口气，随后又觉得窘。这已不是第一次靠一个认识你的人化解危局；如果每回都只说自家兄弟、不必再提，真正的过失便永远由酒席遮着。宋江愿意替你说话，是一份情分，不是你往后可以继续让人难堪的凭证。你看着孔亮，还欠他一句不因认出了宋江才肯说的话。", "spoken": "宋江：先解开，有事慢慢讲。", "choices": [{"text": "向孔亮正式赔礼", "after": "这场和解不只靠宋江一人调停，你自己也承担了该承担的那部分。", "trait": "trust"}, {"text": "谢宋江，但不推卸酒后的事", "after": "你没有把帮你的人拖来替过失担保，旧友反而更愿意相助。", "trait": "restraint"}, {"text": "说明往后愿如何补偿", "after": "一句歉意有了可以看见的后续，误会不必一直留作宴席上的笑话。", "trait": "mercy"}]}], "26": [{"title": "先叫人坐下", "body": "二龙山的风很硬，鲁智深却先叫人端饭。他听你的事，时而皱眉，时而只说一句吃了再讲。你原以为相见须先报本领、论胜负，这大和尚却问路上可有人追、伤有没有养好。杨志坐在一旁，脸上青记使人先记住他的失意，眼神却很稳。这里并非人人清白的所在，但至少有人愿意让你先说完整句话。", "spoken": "鲁智深：能到这里，总不是只为寻一碗好酒。", "choices": [{"text": "不只讲打赢的事", "after": "你把害怕、失算与失控也说出来，故交才知道何时应当拦你。", "trait": "trust"}, {"text": "先向山上诸人问好", "after": "你不将别人的容身处当成自己理所应得的庇护。", "trait": "mercy"}, {"text": "问二龙山靠什么养人", "after": "你开始把一处山寨看成许多人的生活，而不只是一道避追兵的墙。", "trait": "insight"}]}, {"title": "杨志的那把刀", "body": "杨志将刀收入鞘时格外仔细，仿佛曾有一次失去从此让他不肯再随意放下。你们都曾盼凭本领在官府做事，也都见过一身技艺怎样抵不过几句话的算计。但相似并不意味着同一条路：杨志仍不轻易否定官身，鲁智深却常说不如直来直去。你坐在两人之间，发觉朋友可以同桌吃饭，却不必把往后的答案一并说成一样。", "spoken": "杨志：人既有本事，总该有个去处。", "choices": [{"text": "问他真正舍不下的是什么", "after": "你没有急着替他判对错，先听见了他背着的家门与旧望。", "trait": "insight"}, {"text": "说出自己不再愿受的摆布", "after": "你把立场讲明，却没有要求朋友也照着你的遭遇下同一个结论。", "trait": "restraint"}, {"text": "约定有分歧仍先护住同伴", "after": "你们不必处处一样，仍可以给彼此一个不会轻易散去的承诺。", "trait": "oath"}]}, {"title": "夜里没有官差", "body": "入夜后，你听见山风便醒，以为又有押差靠近。守夜的小喽啰告诉你只是换岗，语气自然得像讲一件再寻常不过的事。你躺回去，反而不习惯自己暂时可以不赶路。后来鲁智深提着热水经过，没有追问你为何醒着，只说天亮不急着演武。有人不拿你的疲惫当作软弱，这比一场热闹接风更使你难以忘记。", "spoken": "鲁智深：先养得站稳，往后有的是事。", "choices": [{"text": "把夜哨的路线认清", "after": "你将不安化成具体的了解，不再让每一阵风都变成追兵。", "trait": "insight"}, {"text": "接受明早不必争先的安排", "after": "你允许自己休息，也允许别人看见你并非时刻无伤无惧。", "trait": "restraint"}, {"text": "替夜哨留下半壶热水", "after": "你记住刚才有人怎样待你，也把一点照应传给守着别人睡觉的人。", "trait": "mercy"}]}], "27": [{"title": "粮册上的空白", "body": "山上几张嘴尚可临时对付，一寨人的饭却不能靠一句仗义。粮册上写的是还剩几石，旁边没有写谁已少吃一顿。有人说拦下商队最省事，鲁智深没立刻接话，杨志则问能不能先凑些钱。你知道饥饿会让人急，也知道若因此把所有过路人的粮都拿来，山下百姓便迟早只会盼官兵烧了这座山。", "spoken": "管粮的：头领们讲道理，锅里也得先有米。", "choices": [{"text": "算清全寨最低所需", "after": "你不把节俭只变成要求旁人挨饿，先将能省与不能省的分开。", "trait": "insight"}, {"text": "先减头领席上的酒肉", "after": "你们愿意先承担代价，才有资格请其他人一同熬这几天。", "trait": "mercy"}, {"text": "提议购粮并护送商路", "after": "你开始找一种不靠劫掠也能让山寨与山下相处的办法。", "trait": "duty"}]}, {"title": "商队不敢点头", "body": "商人看见你们的兵器，便连价钱也报得不敢完整。他怕要得多像贪，不要钱又像冒犯。你想做的是买粮，场面却仍像一句客气的勒索。若真要公平，不只是嘴里说按市价便够；你得让他确实有说不、说少一点、说自己还有别处要送的余地。旁边喽啰觉得麻烦，催说给钱已经很客气，你没有立刻附和。", "spoken": "商人：各位要多少，小的尽力便是。", "choices": [{"text": "将兵器与人退远些再议", "after": "商人终于敢把这批粮原本的去处讲出来，交易不再只剩服从。", "trait": "restraint"}, {"text": "明说不愿卖也可放行", "after": "你为一句公平加上可以拒绝的条件，山下的人开始听懂。", "trait": "mercy"}, {"text": "请双方各自验秤", "after": "你不求一笔生意便得美名，只求日后彼此都能照同样的办法再来。", "trait": "insight"}]}, {"title": "多留下的一袋米", "body": "装车时，商人留了一袋，说是给山上伤病者的。他仍有点怕，却已不似初见时一味赔笑。喽啰想把这视作今后可以多取的惯例，你知道这份好意若被收成规矩，刚才费心留下的信任便会立即坏掉。寨中生活并不只在大事上分善恶，许多坏规矩起初也像一件不值得计较的小方便。", "spoken": "商人：只是此番一点心意，往后生意还请照应。", "choices": [{"text": "说明不作往后例规", "after": "你收得下这一回的好意，也守住它不会变成下一回必须交的钱。", "trait": "restraint"}, {"text": "请人将粮送到真有需要者手里", "after": "你不让伤病的名义只给头领们多添几碗酒。", "trait": "mercy"}, {"text": "记下价钱与收支公开给寨中看", "after": "公平既要对着山外，也得能让山里的人看见。", "trait": "insight"}]}], "28": [{"title": "山门来报急", "body": "青州的消息传到二龙山，先来的是一名走得满身泥的小喽啰。不同山头的人要互相接应，旧有恩怨却不因一句聚义就全都消失。你看见杨志问路线，鲁智深先问被围的人还有没有吃的。若只为抢一个先破城的名声，后队、伤者与带路者便容易被当成跟得上就跟的人。你第一次须以头领的身份决定，一支队伍究竟是怎样的一群人。", "spoken": "报信人：急是急，山路上还有好些走不快的。", "choices": [{"text": "先分前队与护送队", "after": "你没有让会打的人全跑到前头，不能快走的也有了归属。", "trait": "duty"}, {"text": "问清各寨谁负责接应", "after": "一句大家都是兄弟之外，真正能找到人的姓名与地点更要写明。", "trait": "insight"}, {"text": "让伤者知道会带上他们", "after": "这句话使后队安静下来，他们终于不必靠硬撑假装自己仍能冲锋。", "trait": "mercy"}]}, {"title": "路口的不同意见", "body": "到了岔路，前哨说近路可快半日，粮队却说那条路装不了车。两种话都是真的，只听其中一种便会显得另一边不够卖力。你已经习惯了独自走险，如今却得为一整队人选路。勇猛在这里未必是赶最快的那个人，有时是肯承认自己不能替别人把一袋粮、一条伤腿变轻。", "spoken": "杨志：人能钻过去，车与担子却不会凭空飞过去。", "choices": [{"text": "保住粮道，再另派轻装接应", "after": "你不让两个合理的需要互相抵消，各有队伍承担。", "trait": "duty"}, {"text": "亲自查看近路再定", "after": "你不逼后队只凭一句头领说能走便往险处挤。", "trait": "insight"}, {"text": "给改道的人留明白标记", "after": "队伍分开不等于彼此丢失，后到的人仍知道该往哪里追。", "trait": "trust"}]}, {"title": "夜宿的火堆", "body": "赶了一日路，先到的人生了火，后到的却连空地都没分到。有人说慢的只怪自己，你想起自己在柴庄等一盆炭的日子，知道这种话最容易在疲累时被说得理直气壮。你若只在白天护他们，夜里又默许人人凭力气抢一块暖处，那些讲过的兄弟便只剩出战前好听的一层。", "spoken": "伤卒：头领，我们靠外些也行，不必为难。", "choices": [{"text": "让头领先挪一半地方", "after": "你用自己的位置替规矩作证，不只叫已经很累的人再忍一忍。", "trait": "mercy"}, {"text": "按轮次分火与守夜", "after": "照顾不再完全靠有人恰好看见，明晚也有能照办的次序。", "trait": "duty"}, {"text": "问清还有谁没有跟到", "after": "你在众人开始歇下时仍点一遍姓名，不让掉队者只剩一句大概快来了。", "trait": "oath"}]}], "29": [{"title": "水泊上的头一夜", "body": "梁山比二龙山大，灯多，人也多。有人早听过打虎的武松，过来敬酒；也有人只把你当作新并来的一个山头。你可以急着让这里认出自己的分量，也可以先看看这地方怎样让不同来历的人同住。一桌饭里能看见很多事：谁替谁讲话，谁只是陪笑，谁添过三回酒仍没有人问他路上可辛苦。", "spoken": "鲁智深：先认人，莫只认交椅。", "choices": [{"text": "去听普通步卒的安置", "after": "你不让换了更大的山寨便意味着更小的人更容易被藏起来。", "trait": "mercy"}, {"text": "同不同山头的队正通姓名", "after": "将来临阵要找的不是一个含糊的兄弟，而是一个真正认得的人。", "trait": "trust"}, {"text": "留意粮仓与伤舍的位置", "after": "你先认清能够维持生活的地方，不只记得议事堂怎样气派。", "trait": "duty"}]}, {"title": "座次落定", "body": "你坐在第十四把交椅上，听见天伤星的名号。堂上有人欢喜，有人默然，许多从前未必相识的人从此要被说作一百单八人。你不否认一场共同仪式能让人有所归属，只是不愿让它替所有人的心事作答。你与鲁智深交换一眼，知道旁人排定的位置不等于自己日后只能照一个写好的结局往前走。", "spoken": "心声：天上怎样排，人间的事还得人来办。", "choices": [{"text": "把座次换成具体职分", "after": "你问清自己该管哪些兵、照顾哪些伤病，不只收下一声好名号。", "trait": "duty"}, {"text": "记住与旧友的互照约定", "after": "人多以后，你更不愿让熟悉的人被一场宏大的说法悄悄吞去。", "trait": "oath"}, {"text": "不因高低轻看新来的头领", "after": "你知道坐得靠后的人同样会在战场上受伤，同样有人等他们回家。", "trait": "mercy"}]}, {"title": "第一张队规", "body": "步军归你管的一部分，要练的本事很多，写下的规矩却先争在酒与钱上。有老兵笑说山上不是官军，何必也抄那些文书。你见过一张纸怎样被官府滥用，也见过没有纸的人怎样被一句没说过便抹掉承诺。规矩本身未必站在哪一边，要紧的是上头管不管得住拿刀的人，以及出了事是否有人真肯照办。", "spoken": "老兵：写了不算数，还不如只说一句。", "choices": [{"text": "先将头领也写入处罚之内", "after": "规矩不再只是约束更弱者的东西，众人才开始认真看。", "trait": "duty"}, {"text": "让兵卒也提一条要求", "after": "你不让命令只有一方会写，会受其影响的人也有权指出难处。", "trait": "trust"}, {"text": "把不害百姓列在开头", "after": "你给日后的每次出手留下一把能衡量自己的尺子。", "trait": "mercy"}]}], "18": [{"title": "箱子是谁搬的", "body": "府中叫起捉贼声时，武松的箱子已被人搬出房门。你问谁先开过锁，守门人却只催快去见大人。大家急着看箱里有什么，仿佛东西一旦从中拿出来，先前谁能进房便不再重要。你知道此刻越是声大，越容易让所有话只剩你在喊冤；但不争这一句，往后他们便能说箱子从来只在你自己手里。", "spoken": "守门人：不要东问西问，到了堂上自有分晓。", "choices": [{"text": "记住搬箱的两个人", "after": "你将姓名与时辰默记下来，不让眼前的慌乱抹掉经手的人。", "trait": "insight"}, {"text": "请当值者说出门锁何时打开", "after": "你没有碰箱子，只让一个本该寻常的问题留在众人耳里。", "trait": "restraint"}, {"text": "不让无涉仆役替自己争吵", "after": "你先保住愿意说话的人，免得他们同你一并被扣住。", "trait": "mercy"}]}, {"title": "一整齐的口供", "body": "搜检来得太顺了。金银恰在该出现的时候出现，几个仆役连你何时独处都答得整齐，却对自己前后去哪儿含糊起来。你想到了阳谷县的供状：真话未必完全一样，排练过的话倒常常不留一点差别。可是你没有纸，也没有人替你落笔，必须在身上又冷又痛的时候记住这些细处，等待一个还肯来探你的人。", "spoken": "张都监：待你这般好，你还有什么好辩？", "choices": [{"text": "抓住一处时辰矛盾追问", "after": "你没有把力气全耗在骂人，留下了一句对方不愿回答的问题。", "trait": "insight"}, {"text": "把经过按先后在心里重复", "after": "你给日后的自辩留下一条稳的线，不任愤怒将事情搅成一团。", "trait": "restraint"}, {"text": "请人转告施恩自己被拘", "after": "你知道此时最急的是让外头的人知道，自己并非收了恩便失去踪影。", "trait": "trust"}]}, {"title": "门内忽然生分", "body": "昨日喊你壮士的人，今日改口叫贼。你这才看清，有些体面原来只是一种随时能收回的称呼。被押离张府时，你看到曾递过热水的仆役低着头，不敢看你。你可以把他的沉默也算进仇里，但他未必比你更有得选。真正握着钥匙、叫得动兵的人仍坐在厅中，若让愤怒朝每个更弱的人散开，便又替他们遮住了该承担的罪。", "spoken": "心声：我得记住害我的是谁，不是谁没能救我。", "choices": [{"text": "不辱骂低头的仆役", "after": "你把账留给作局的人，没有让一个怕事的人替权势受过。", "trait": "mercy"}, {"text": "记下守门与押解的交接", "after": "你不再盼一句体面称呼，开始找能把事接起来的实际节点。", "trait": "insight"}, {"text": "守住呼吸，少作无用挣扎", "after": "你留一点力气给真正能逃出生天的时刻。", "trait": "restraint"}]}], "19": [{"title": "来探的人也带伤", "body": "施恩到牢里时比先前瘦，脸上的新伤也遮不住。他说快活林又落回去了，连自己父亲也受了逼迫。你若此时只听得见一句你害我，便会将这个仍肯来的人一并推走；但你也不能为了让他好受，就把他从前隐瞒的关系全都忘掉。朋友不是永远没有亏欠的人，而是在亏欠说清以后，还肯做一点实际的事。", "spoken": "施恩：都怪我，使哥哥陷到这般地步。", "choices": [{"text": "先问他是否还受人监视", "after": "你没有只顾自己要消息，也留意这个来送饭的人能否平安离开。", "trait": "mercy"}, {"text": "请他把张府与蒋门神的关系讲透", "after": "你不再接受含糊的解释，施恩也终于把听来的往来逐一说清。", "trait": "insight"}, {"text": "说明怨归怨，仍谢他来", "after": "他不再急着为自己辩解，反肯认真商量下一步可以做什么。", "trait": "trust"}]}, {"title": "饭里的消息", "body": "牢中饭食粗坏，施恩带来的热饭使你终于能慢慢咽下。吃饭间，他将新消息压低声音讲出：谁去见过谁，谁放话要你不能活着回头。每一条都可能有误，也可能是救命的一环。你记得十字坡那对夫妻给过接应的余地，便开始想，哪些话可以交出去，哪些事又不能让一个送信人全都知道。", "spoken": "施恩：哥哥要我带什么话，今日便赶紧说。", "choices": [{"text": "只托他传一件确定的消息", "after": "你让口信简短而可核，不把整条退路压在一人口舌上。", "trait": "insight"}, {"text": "请他不要再独自冒险", "after": "你不愿把自己的生路建立在朋友一次次挨打与求人的身上。", "trait": "mercy"}, {"text": "定一个消息转交的见证", "after": "即使有人截住一段话，仍能从别处知道这条联系没有断。", "trait": "trust"}]}, {"title": "不肯写的认罪话", "body": "看守递来一份拟好的供词，声称认了便能早些发配，不认只会再受苦。上头把被搜出的银钱、前日宴席和你旧日的罪都连成一条，读起来竟像你从来就在等机会偷盗。你知道一笔签下可能换来眼前少痛一点，也知道它日后会反过来堵住一切辩解。你不必为每一字都与他们拼命，却得选清哪些字不能由你的手认下来。", "spoken": "看守：写个名而已，何必与自己过不去。", "choices": [{"text": "指出自己不曾承认的部分", "after": "你守住了最关键的界限，让他们不能轻易拿模糊话说你全认了。", "trait": "restraint"}, {"text": "请求把受审过程一并记录", "after": "即使对方不肯，你也让旁边的人听见你曾提出这个要求。", "trait": "insight"}, {"text": "把可能受牵连的姓名划去", "after": "你不为减轻自己的苦，将知情者和送饭的人一同拖进罪里。", "trait": "mercy"}]}], "20": [{"title": "押解之前", "body": "通知发配时，天色还暗，押差却催得极急。你想问终点与交接，得到的回答每回都不同。路上先前有人装作随意打听你伤势，眼前这两个人又格外在意枷锁是否扣牢。你不是无端怀疑每个奉差的人，只是已经见过一场要做成既成事实的局。离开牢门后，你需要随时知道自己身后有没有路。", "spoken": "押差：少问，赶到前头歇脚，自会让你吃饭。", "choices": [{"text": "记下离城后的岔路", "after": "你将方向留在脑中，不让一味赶路使自己对周遭全无判断。", "trait": "insight"}, {"text": "调整枷锁，不让双肩僵死", "after": "你用能做到的小动作保住转身的可能，而不是凭空等力气回来。", "trait": "skill"}, {"text": "不与押差争每一句话", "after": "你把注意力留给真正异常的行动，不被几句恶声抢走。", "trait": "restraint"}]}, {"title": "桥头的四双脚", "body": "两个持刀的人并上来以后，押差反倒慢了。桥上没有许多可走的地方，四双脚却都想抢到一个便于合围的位置。你看见其中一人刻意让开水边，又瞥向枷锁的缝隙，便知道他们担心的是什么。你此刻最危险的念头，是急于让他们知道自己已经看穿；一旦先亮明白，尚未扣紧的网便可能立刻收拢。", "spoken": "心声：看见了，也须等能动的时候再动。", "choices": [{"text": "装作疲乏，观察他们站位", "after": "你不与他们比谁先出声，先让四个人的用意显到脚下。", "trait": "insight"}, {"text": "借歇脚调整重心", "after": "你给脱枷的劲找到了可以落下的位置，不把全力用在半空。", "trait": "skill"}, {"text": "问一句地名，试其反应", "after": "其中一人答得太快，你从不自然的轻松里听见了蓄意。", "trait": "restraint"}]}, {"title": "还没有断开的木枷", "body": "你用手指试了一处木纹，明白这不是凭怒气便能一下扯开的东西。身上旧伤仍在，河水又响得盖过细小动静。若出力太早，几个人会同时压上；若等得太晚，脚下就再没有能借力的石头。你想到冈上断棒的一声，知道手中之物不是全部依靠，自己的眼与脚也不能白白交给这四个人。", "spoken": "交锋：先取回一个能发力的身位。", "choices": [{"text": "引最近的人伸手来推", "after": "你等他靠得足够近，借同一股力把包围撕开一点。", "trait": "skill"}, {"text": "把目光落在刀而非喊声上", "after": "你不让叫骂催乱自己，看清了哪只手是真要落下来。", "trait": "insight"}, {"text": "稳住脚，等对方互相遮挡", "after": "你没有追求漂亮，只求在最窄的地方替自己留出一条活路。", "trait": "restraint"}]}], "21": [{"title": "前走还是回头", "body": "飞云浦已经在身后，往前走便能暂时离开追杀你的人。你却从押差的话里知道，孟州今夜有人正为这场谋害放心吃酒。回头意味着再入城门，意味着把刚赢来的命又放到桌上。你不能把这选择说成只有一种才叫好汉，也不能骗自己只是回去问一句话。你若决定回去，便须先想清楚究竟要讨哪一笔账。", "spoken": "心声：逃过一劫的人，仍有权选择余下的路。", "choices": [{"text": "先将主谋与旁人分列", "after": "你把具体姓名留在心里，不让整座宅院都因一股怒火变成仇人。", "trait": "restraint"}, {"text": "寻一处隐蔽地方整伤", "after": "你知道回城需要的不只是恨，还要有撑到离开的气力。", "trait": "skill"}, {"text": "给十字坡留一条口信", "after": "你不再让外头的人只从传闻里猜自己死在了哪条路上。", "trait": "trust"}]}, {"title": "换一道城门", "body": "孟州城的门路你来时看过，今日却不能再按受邀宾客的路走。卖夜食的人收了摊，巡夜者的灯一明一暗。你若为了省几步便强闯，最先被惊动的未必是主谋，而是满街无涉的人。你俯身在一处墙影下等过去的脚步，觉得这比出拳更难：越急着讨还，越得先承认自己不能任意支使整个城里的夜。", "spoken": "心声：我回来，不是叫这一城替我陪葬。", "choices": [{"text": "绕开住户密集的巷子", "after": "你宁肯走得更远，也不把追捕引向刚关上门的人家。", "trait": "mercy"}, {"text": "认清巡夜的间隔", "after": "你用观察替自己开路，没有把每一个当值的人都变成敌人。", "trait": "insight"}, {"text": "留出出城后的第二条路", "after": "清算不能只想进得去，还得为活着离开保留可能。", "trait": "restraint"}]}, {"title": "灯外听见自己的名字", "body": "你尚未上楼，便听到席上人说起飞云浦。笑声里有自己的名字，有押差，有一份以为已经办妥的赏钱。你曾期待一个明白证据就肯听的人，如今终于听见主谋毫不遮掩，心里却没有轻松。真相并不总带来清白归来的路，有时只让你再不能假装那场宴席曾是善意。你站在暗处，需要为接下来每一个动作负责。", "spoken": "楼上传来一句：那厮如今，还能往哪里去？", "choices": [{"text": "再听清参与者各自所言", "after": "你不因已经愤怒便略过事实，让主谋的账不至于算到无涉人头上。", "trait": "insight"}, {"text": "压住抢先出声的冲动", "after": "你把自己留在能够选择的地方，不在一声怒喝后只剩拼命。", "trait": "restraint"}, {"text": "先看仆役有无避走的路", "after": "你将一条生路留给并未坐在那席酒上的人。", "trait": "mercy"}]}], "22": [{"title": "门槛以内", "body": "门开的一瞬，三人从酒席上回头。你先看见他们认出自己时的惊惧，随后才听见那些熟悉的称呼重新回来：壮士、兄弟、误会。眼前这些话曾叫你相信自己终于可以堂堂正正活着，如今再听，只觉得每个字都轻。你可以用他们的恐惧抵消自己受过的一切，也可以记住，恐惧本身不是一张允许你任意行事的凭据。", "spoken": "张都监：有话好说，莫惊了府里人。", "choices": [{"text": "点出飞云浦与赏钱", "after": "你把话落在他们已做过的事上，不再听空泛的抬举与求情。", "trait": "insight"}, {"text": "让无涉仆役先退开", "after": "清算开始以前，你先划出不能越过的界限。", "trait": "mercy"}, {"text": "不因求饶而改写真相", "after": "你可以选择如何收刀，却不能让他们一句误会便抹掉整场谋害。", "trait": "restraint"}]}, {"title": "留在墙上的话", "body": "你想到若自己不能活着出去，城里便只会听见张府怎样讲这个夜晚。有人或许会把你说成受恩不报的恶客，也有人会替你编出更吓人的故事。你无力替后人定好所有说法，但可以留下一个不肯藏名的人所应担的责任。刀上的胜负解决不了这一层，你需要的是让事情有一段可以被追问的始末。", "spoken": "心声：我不能让他们替我说，也不能叫旁人替我认。", "choices": [{"text": "留下主谋与谋害的经过", "after": "你写的是自己能够承担的所见，不把无涉人一并钉进故事。", "trait": "insight"}, {"text": "明言行事者是武松", "after": "你没有借别人的姓名脱身，也不让下一场追查先去找更弱的人。", "trait": "restraint"}, {"text": "带走能证明栽赃的物件", "after": "你为那句喊了许多次的冤屈，留下一点不只靠声音的东西。", "trait": "trust"}]}, {"title": "下楼以前", "body": "楼外雨声没有因为胜负停下。你往楼梯走，发现手指仍紧得很，不像想象中报仇之后便能立刻松开。下面有人哭，有人躲，有人根本不知道楼上发生了什么。若把所有动静都当作阻拦，剩下的每一层楼都会有新的仇。你在踏下第一阶前停了一息，知道真正困难的，不是再挥一次刀，而是决定这一夜到哪里为止。", "spoken": "心声：已经讨过的账，不能再向无辜的人讨。", "choices": [{"text": "给躲避者留下出口", "after": "你不让手中的刀继续扩大它本来要清算的范围。", "trait": "mercy"}, {"text": "确认追兵方位再离开", "after": "你把警惕留给真实的危险，而不是将害怕的人都当作敌手。", "trait": "insight"}, {"text": "将刀收到不易误伤人的位置", "after": "离开险地也需要克制，你第一次认真觉出收刀的分量。", "trait": "restraint"}]}], "23": [{"title": "敲开旧店门", "body": "十字坡的门在深夜开了一条缝，张青认出你以后没有立刻问杀过多少人，而是让你先进来。孙二娘看你衣上的泥雨，先拿来干布。你背着刚做过的事坐下，忽然不知道该从何讲起：是张府的抬举，牢里的供词，还是桥上的四个人？如果此时只说一句官府容不得我，便把自己也容不得直视的部分藏了起来。", "spoken": "张青：先把路上发生的，说与我们听。", "choices": [{"text": "连自己越过的界限也说", "after": "你不只挑能叫人同情的部分讲，救你的两人因而更清楚怎样帮你。", "trait": "insight"}, {"text": "先问追兵会否连累店里", "after": "你没有把愿意开门的人当作可以任意借用的藏身处。", "trait": "mercy"}, {"text": "谢过接纳，先将身子暖回", "after": "你接受帮助，不再把忍着一切说成唯一体面的活法。", "trait": "trust"}]}, {"title": "数珠与旧衣", "body": "孙二娘拿出的装束有来历，不是替逃犯随手剪一块布。戒箍、数珠、两口戒刀，都有它们曾经属于的人，也有足以使路人不再立即认出都头的样子。你摸着旧官服，才发觉自己先前费了多少力气去相信那身衣能给人一个正当身份。如今另一套衣裳又要替你遮身，可你不想再让衣服替自己决定能做与不能做的事。", "spoken": "孙二娘：头陀的样子好改，脚下的路还得自己认。", "choices": [{"text": "仔细学这身衣物怎样穿戴", "after": "你不把伪装只当作一顶帽子，连行走时会露出的旧习也一并留意。", "trait": "insight"}, {"text": "给自己立一条真正的戒", "after": "不论旁人如何看这身衣，你先决定有些事往后不再任意去做。", "trait": "restraint"}, {"text": "与夫妻二人约定患难来往", "after": "你记住开门的人，也愿意在他们需要时承担同样的风险。", "trait": "trust"}]}, {"title": "另一种姓名", "body": "水里映出的脸仍是自己，额上却多了铁箍，身边多了戒刀。行者两字听来可以解释许多事：为什么独走，为什么不轻易谈籍贯，为什么眼神不似寻常僧人。你若只借它避过一阵官兵，旧日性情仍会从每次动手里把自己认出来。你从来不是换过一个名字便少了因果的人，只是如今终于有机会为往后的路添上一条自己认可的规矩。", "spoken": "心声：做行者，也得知道究竟往哪里行。", "choices": [{"text": "先想清下一处可靠去处", "after": "你不再只为离开眼前的危险而赶路，也给下一日留一个可抵达的地方。", "trait": "insight"}, {"text": "将旧官服妥善收下", "after": "你不必永远穿着它，却也不以烧尽过去假装一切从未发生。", "trait": "restraint"}, {"text": "向恩人说明可能的联络处", "after": "行者不是再无牵挂的人，你仍肯给别人留下找得到自己的路。", "trait": "trust"}]}], "12": [{"title": "枷外的人", "body": "离开阳谷时，你已不能自己抬手整理领口。木枷把脖子与肩膀压在一起，押差每走快一点，边缘便磨得更痛。街边有人认出打虎的都头，目光从敬畏变成躲闪，仿佛换了这一副物件，你过去做过的事也全都变了。你不能要求他们都来相送，却仍可决定自己怎样对待这两个奉命同行的人。", "spoken": "押差：路还长，莫在头一日便使尽了力。", "choices": [{"text": "问他们沿途如何安排", "after": "你把自己重新放回可以商量的处境，不只与一副枷锁较劲。", "trait": "trust"}, {"text": "慢些走，及时说明磨痛之处", "after": "忍到伤口溃烂并不比开口更勇，你为长途留下一点本钱。", "trait": "restraint"}, {"text": "记住沿途关验手续", "after": "你看清谁能改文书、谁只照册办事，官府不再是一个含糊的名字。", "trait": "insight"}]}, {"title": "酒碗里的异样", "body": "十字坡酒家给客人的笑脸太熟练，酒又送得太快。你从前讥笑别人在酒里下药，此刻却不能再把这种可能只当作一句骂话。孙二娘绕过桌角，手上忙着，眼睛始终没完全离开你。你若误会了一个做生意的人，先动手便难收拾；若只因怕失礼便将酒喝下，也等于把三个人的安危交给一句招呼。", "spoken": "孙二娘：路上辛苦，趁热吃了好走。", "choices": [{"text": "闻过酒气，再用话试探", "after": "你没有贸然入口，也没有立刻把猜测叫成罪名。", "trait": "insight"}, {"text": "与押差分明约定先后吃喝", "after": "不论眼前是不是陷阱，你先让同路的人不至于一齐失去防备。", "trait": "trust"}, {"text": "推开酒碗，只吃干粮", "after": "你宁肯饿一点，也不拿清醒换桌上的热闹。", "trait": "restraint"}]}, {"title": "一场险后的称呼", "body": "张青回来时，店里的气氛已经绷紧。他看清你的身量、枷上的来历，再听到武松的姓名，态度忽然不同。你知道江湖名声能替人解围，也可能让人忘了刚才真正危险的是什么。双方既已说开，便不能只靠一顿赔酒将先前的算计轻轻揭过；你要与他们相交，须先知道他们肯为哪条界限停手。", "spoken": "张青：既是武二郎，先前多有得罪。", "choices": [{"text": "把误会说透再论交情", "after": "你们不再假装什么都没发生，往后的信任有了可以站住的地面。", "trait": "insight"}, {"text": "说明同行押差也须平安走", "after": "你的名声不能只保你自己，这两个无权势的人也在承诺之内。", "trait": "mercy"}, {"text": "谢过留宿，却不纵酒", "after": "你留住新交情，也留住了第二日出发时清楚的头脑。", "trait": "restraint"}]}], "13": [{"title": "牢城的门槛", "body": "孟州牢城门口，旁人先向你讲杀威棒的规矩，又暗示送些银子便能少受一点。你见识过县衙推托，却仍为眼前这种明着开价的日常觉得心冷。受打可能伤身，送钱又会让本就不多的盘缠迅速见底。更难的是，若只有有钱的能免，你旁边那些连草鞋也补不起的人，又该怎样熬过这一道门。", "spoken": "老囚：有的人不是输在路上，是进门这一天便伤了根本。", "choices": [{"text": "先问清是谁管这条规矩", "after": "你不急着把钱递给第一个伸手的人，先认准真正能说话的所在。", "trait": "insight"}, {"text": "替同行老囚分一点吃食", "after": "你此刻不能改尽牢城，却仍能让眼前这个人不空着肚子挨罚。", "trait": "mercy"}, {"text": "把随身盘缠分处收好", "after": "你不让一次搜检或一场勒索就将所有退路一并拿走。", "trait": "restraint"}]}, {"title": "没有落下的棍子", "body": "原定的杀威棒忽然免了。看守说你途中病着，姑且记下，语气却不像真的在关心伤病。随后有人送来干净被褥，热饭也比旁人好。你当然需要这些，可需要并不意味着能把它们看成没有来处。牢中最贵的东西有时不是一碗肉，而是让一个人习惯了特殊照应以后，再开口请他替自己办事。", "spoken": "看守：小管营吩咐，先让你养着。", "choices": [{"text": "问清小管营的姓名", "after": "你先记住施恩这个人，不让受惠变成对一个模糊影子的亏欠。", "trait": "insight"}, {"text": "留一份饭给近旁病囚", "after": "你不愿自己的好处只靠与旁人隔出一条看不见的线。", "trait": "mercy"}, {"text": "收下被褥，但不许下空口承诺", "after": "你感谢照料，却没有答应一件尚未讲明白的事。", "trait": "restraint"}]}, {"title": "送饭的人不说缘故", "body": "施恩亲自来探，衣着体面，脸上却有一处不愿多说的旧伤。他问你好不好睡，吃不吃得惯，始终不提为何厚待。你能感觉到他在等你主动开口，仿佛这样一来，事情便更像你自愿替朋友解围。可你们尚不算朋友，至少还未听过彼此最难听的实话。你将碗放下，想让这份关照从试探变成一场能说清的对话。", "spoken": "施恩：别的事不急，哥哥先养好身子。", "choices": [{"text": "请他讲出真正的难处", "after": "施恩停了很久，终于不再只用客气话绕着快活林打转。", "trait": "trust"}, {"text": "先问脸上的伤从何而来", "after": "你从一个具体问题入手，听见了被人夺去产业的经过。", "trait": "insight"}, {"text": "说明帮忙也有不可做之事", "after": "你不愿等承诺出口以后，才发现自己成了另一场欺人的凭借。", "trait": "restraint"}]}], "14": [{"title": "谁收这一路钱", "body": "施恩讲快活林时，先说自己被夺去的店，又说往来人客怎样交钱。你听了一会，发觉其中不全是干净生意。蒋门神仗着张团练欺人，施恩从前也靠父亲在牢城的势力得利。你若只因一方对自己好，便把全部是非替他涂白，这一拳与别人拿权势压人又有什么分别？施恩看你不说话，渐渐放低了声音。", "spoken": "施恩：哥哥若嫌这事情不体面，我也无话。", "choices": [{"text": "请他把账里的进项说完整", "after": "你不只听最能激怒自己的那一半，帮忙前先看见整件事。", "trait": "insight"}, {"text": "说明不替任何一方欺客", "after": "施恩知道你肯帮，却不能拿你的名声继续沿用旧日恶规。", "trait": "restraint"}, {"text": "问被夹在中间的店户", "after": "你让没被邀请上酒席的人，也能说说自己到底失了什么。", "trait": "mercy"}]}, {"title": "一张不敢抬头的脸", "body": "快活林的卖面老汉见施恩便赔笑，见到你时又赶紧多拿一只碗。他未必知道该向谁诉苦，只知道换一次主人，便可能重新交一次钱。你问前几日的事，他先看看门外，才说蒋门神的确更狠。一个更狠的人出现，不会自动使从前的人都成好人；你若想替朋友拿回什么，也得想好这老汉以后还要如何开门。", "spoken": "老汉：有个定规就好，莫今天这样，明天又那样。", "choices": [{"text": "把他盼的规矩逐条记下", "after": "你将助拳的条件落在店户能看见的地方，不只放在两个人的酒话里。", "trait": "mercy"}, {"text": "让施恩当面答应不加收", "after": "承诺有了第三个人听见，日后便不那么容易装作没说过。", "trait": "trust"}, {"text": "不当场逼老汉选边", "after": "你不让弱者为了得到一点照顾，还得先冒着罪另一边的险。", "trait": "restraint"}]}, {"title": "朋友的难堪", "body": "回去路上，施恩几次想解释。他觉得你既吃了他的饭，便应当知道自己不是坏人；你却不能拿受过照应作全部判断。他的难堪也是真的，父亲年老，手下人散去，原本仰赖他的那些生计眼看维持不住。你要与他谈的不是谁比谁更清白，而是如果这次真能夺回快活林，愿不愿借机改掉那些从前觉得理所当然的事。", "spoken": "施恩：照哥哥说的办，还能赚得出活路么？", "choices": [{"text": "与他算一笔不靠逼索的账", "after": "你让他看见少取一点未必就要倒闭，事情开始有了别的做法。", "trait": "insight"}, {"text": "告诉他恩情仍记着", "after": "你没有因为指出过失就否定全部好意，朋友才更可能听进后半句话。", "trait": "trust"}, {"text": "不急着催他当场应诺", "after": "你给他一夜思量，也给自己留着不被一顿酒绑住的权利。", "trait": "restraint"}]}], "15": [{"title": "门前的两张凳", "body": "蒋门神坐在门口，没动手就先占住了路。他的体格、名声与张团练的倚仗一起压过来，仿佛要你先承认这里只能由他说了算。你看见凳脚、门框与地上的水迹，知道眼前不是一处平整的演武场。你可以让他以为你醉得站不稳，却不能让自己真的醉到忘了这些东西。", "spoken": "蒋门神：你这过路人，也来问快活林的规矩？", "choices": [{"text": "先看门框可借的身位", "after": "你没有被大块头吓得只顾抬头，看清了如何把他的力引向空处。", "trait": "skill"}, {"text": "把旁观店户请离近处", "after": "你不拿他们的摊子与身子当自己比武时的遮挡。", "trait": "mercy"}, {"text": "用言语引他先离座", "after": "你试的不是嘴上胜负，而是他起身时哪条腿更迟。", "trait": "insight"}]}, {"title": "醉与未醉之间", "body": "你斜着步子往前，蒋门神眼里已经有了轻慢。围观的人以为只是酒客发疯，只有你知道几步虚浮是做给谁看的。可装醉也有危险：若为了像一点便真把重心放歪，对手的一脚就足够让戏变成实情。你回忆自己练过的玉环步与鸳鸯脚，心里不是一串招名，而是对方什么时候会把重量交给一只脚。", "spoken": "交锋：让他觉得你要倒，不要真的让自己先倒。", "choices": [{"text": "用虚步试出他的追击", "after": "他果然急于补上一脚，你得到的破绽比争一句痛快更实在。", "trait": "skill"}, {"text": "留意身后凳脚", "after": "你没有在对手未到时先绊住自己，也不再靠运气护住脚跟。", "trait": "insight"}, {"text": "少进半步，保留转身", "after": "这一点收住的距离，替下一次发力留下了整副身子。", "trait": "restraint"}]}, {"title": "摔倒之后", "body": "蒋门神倒地，周围的人立刻想挤上前。有的要出气，有的只想看热闹。你用脚压住的那个人刚才还不可一世，如今倒比站着时更容易受伤。你若任众人一拥而上，便无法再说这是自己与他的比武；若只赢一场就走，快活林明日仍可能照旧。胜负已分，接下来的一句话才决定这一身本事替谁起了作用。", "spoken": "施恩：哥哥，须叫他再不敢回来！", "choices": [{"text": "让他在店户前讲明去留", "after": "你要一个能落实的收手，而不是只听一句怕了你的狠话。", "trait": "insight"}, {"text": "拦住旁人继续殴打", "after": "你为自己赢来的场面立界限，不让报复在人群里越滚越大。", "trait": "restraint"}, {"text": "先看有无店户在混乱中受伤", "after": "你没有因为所有目光都看着自己，就忘了边上的普通人。", "trait": "mercy"}]}], "16": [{"title": "开门的第一日", "body": "快活林重新开张，施恩忙着招呼，旧伙计个个说你是大恩人。你走过柜前，却听见一个新来的伙计仍按从前的办法向客人多要钱。若你笑着当作小事，新规矩便只存在过昨夜那顿答谢酒里；若当众把施恩骂得下不来台，也未必能让他愿意长久改变。你得把武力带来的短暂服气，慢慢变成无需你站在门前也能照办的事。", "spoken": "伙计：旧例一直如此，小的也只是照着做。", "choices": [{"text": "请施恩当面改清价目", "after": "你让规矩落到每天做买卖的人手里，客人也知道自己该付多少。", "trait": "insight"}, {"text": "先退回多收的钱", "after": "受损的人先得到补偿，而不是站着听两位好汉讲道理。", "trait": "mercy"}, {"text": "说明下回由谁来查", "after": "新规不再只靠想起来时有人发一句火，责任有了具体去处。", "trait": "restraint"}]}, {"title": "一份厚礼", "body": "施恩送来的银子不少，说是心意，不许你推。你看着银两，想到其中有店户旧日交出的辛苦钱，也想到自己流配以来的狼狈。收得太多，日后再劝他改事便容易被一句你也得过好处堵回去；全不收，又未必是能维系朋友情分的唯一方式。钱本身不会替你决定善恶，但怎样拿、拿去做什么，会让话的分量不同。", "spoken": "施恩：哥哥替我拿回的，远比这多。", "choices": [{"text": "只取养伤与路用的一份", "after": "你把报酬的边界说清，日后仍能坦然劝他收住手。", "trait": "restraint"}, {"text": "请他替旧伙计补发欠账", "after": "你让感激不只流向出拳最响的那个人。", "trait": "mercy"}, {"text": "先问账上是否真有余裕", "after": "你不肯为了体面受礼，反让店里明日又须多抽过客的钱。", "trait": "insight"}]}, {"title": "名声成了靠山", "body": "有客人认出你，求你替他向别家索一笔模糊的欠账，说只要站过去露一露脸便够。事情听来不像打架，却一样在借你的名声压人。你刚以为自己替快活林定了新规，眼前便有人想把你变成新的门神。你终于明白，坏事不一定总叫你挥拳；有时候只需让别人以为你随时会挥拳，便足以夺走他辩解的机会。", "spoken": "客人：不用动手，谁敢不认武都头？", "choices": [{"text": "先听欠账另一方说法", "after": "你不让一个递来酒碗的人，轻易借走你替别人决定是非的本事。", "trait": "insight"}, {"text": "拒绝只凭威名替人收账", "after": "你明确说出名声也有不能拿来做的生意。", "trait": "restraint"}, {"text": "请双方按凭据对账", "after": "若真有欠付，仍能讨还；若只是欺压，也不能再躲在你身后。", "trait": "mercy"}]}], "17": [{"title": "军官的口信", "body": "来请你的军汉衣甲齐整，措辞也客气。他说张都监久闻你的本领，愿意抬举一个被埋没的英雄。你在流配路上受够了白眼，太明白这几句话为什么动人。施恩却显得不自在，一会说是好事，一会又说军门深。越是能解掉眼下难处的机会，越容易叫人不愿把不对劲的地方问到底。", "spoken": "来使：大人请的是武壮士，不是寻常配军。", "choices": [{"text": "问明去后以何身份居住", "after": "你不愿只听一个好听的称呼，还要知道它在公文与差事里算什么。", "trait": "insight"}, {"text": "把邀请之事告知施恩父亲", "after": "有人知道你被谁请去，往后便少一处能任人改口的空白。", "trait": "trust"}, {"text": "先收拾好随身物件", "after": "你盼着新机会，也没有把离开时最需要的东西随便留在别人手里。", "trait": "restraint"}]}, {"title": "宅中的灯火", "body": "张府比你住过的客馆气派得多，仆役替你接包袱，酒菜也来得及时。张都监不提囚籍，只说英雄一时失路不算什么。你自然想相信：也许真有人愿意越过案上的罪名，看见你能做的事。但你曾在阳谷衙门里看过另一种脸，眼前越是温厚，便越得提醒自己，不要把一个人的礼貌先当成一份永远不会变的担保。", "spoken": "张都监：到我这里，只管当作自己家。", "choices": [{"text": "谢过款待，仍记清门户", "after": "你让感激与清醒一同留下，没有因为一席好话就交出全部防备。", "trait": "insight"}, {"text": "少饮几杯，把来历说实", "after": "你不靠吹嘘讨好，也不给醉后失言留下可以任人摆弄的余地。", "trait": "restraint"}, {"text": "记住照应自己的仆役姓名", "after": "这些人未必能左右主人的心意，却是宅里真正看见日常的人。", "trait": "trust"}]}, {"title": "不愿回头的好日子", "body": "几日之后，你开始习惯这里的饭食与称呼。有人教你府中哪些地方不能去，又在另一次说大人待你不同，不必拘谨。两种说法都像给了恩典，实际却叫你更难知道边界。你听见后院有人提到蒋门神，声音很快止住。若你此刻只为保住来之不易的体面，便可能把最该问的事也一并替别人藏好。", "spoken": "心声：抬举我的人，为什么不能让我把疑处问完？", "choices": [{"text": "留意蒋门神与张府的往来", "after": "你没有立刻认定阴谋，却开始把原本分开的名字放在一起看。", "trait": "insight"}, {"text": "将近况托人转告旧友", "after": "你不因眼前待你好便断了从前的联系，外头仍有人知道你在何处。", "trait": "trust"}, {"text": "保留能自己离开的盘缠", "after": "你不让一份恩典变成连告辞也得先求准许的处境。", "trait": "restraint"}]}], "42": [{"title": "不再有点卯声", "body": "六和寺的早晨没有先响起军令。你醒得仍早，听了一会，只听见江潮与扫地声。一路以来，你总在担心赶不上、退不了、来不及；忽然无人催促，反倒像少了能替自己解释该做什么的东西。寺中道人送来粥，说不必急着还碗。你端着，第一次认真面对一个不以战功或逃亡作理由的日子。", "spoken": "道人：住在这里，先将饭吃好便是。", "choices": [{"text": "帮着做一件力所能及的小事", "after": "你不必立刻成为谁口中的高僧，只需把眼前一处地扫净。", "trait": "care"}, {"text": "在江边走一段不赶路的路", "after": "你让脚步不再只为抵达一个能救命或索命的地点。", "trait": "freedom"}, {"text": "把未交代的军务逐一写下", "after": "你想离开，也仍愿将该负责的部分交清，不把残局留给别人。", "trait": "duty"}]}, {"title": "寺外也有生活", "body": "寺外有挑担的人，江上有人等渡，遇见你时他们并不都知道打虎的名声。你有些不适应，又有一点轻松。一个摊主只问你买不买热食，没有追问空袖从何而来。你想到哥哥也曾这样站在担子边，知道寻常生活并非比英雄故事低一等的东西；只是自己从前总走得太急，没有站住看它怎样一天一天维持下去。", "spoken": "摊主：想吃便坐，风里站久了凉。", "choices": [{"text": "同他谈一谈生意与江潮", "after": "你学着不以过往功劳作每次相见的开头，仍能好好同人说话。", "trait": "care"}, {"text": "问起船路与远处港口", "after": "世界没有因战事结束而变小，你开始想象不带军令的远行。", "trait": "freedom"}, {"text": "留意往来伤卒有无安置", "after": "你发现能替人做的事仍在，只是不必每一件都先拔刀。", "trait": "duty"}]}, {"title": "朋友的闲话", "body": "鲁智深看着江水，说这里山川真好。你们说起二龙山吃过的一顿饭，竟比谈多少场险仗都自然。他没有催你赶快想通，也没有因为你断了臂就将你当成不会再有脾性的人。你忽然想将这一段留得久些，却也明白不能让朋友永远替自己挡住悲伤。你愿不愿意开口说舍不得，比再陪他饮一顿酒更难。", "spoken": "鲁智深：咱们从前，倒像只顾着赶路。", "choices": [{"text": "说往后还想与他一同看山", "after": "你把不带功名的盼望讲给朋友听，而不是藏到来不及的时候。", "trait": "oath"}, {"text": "承认自己不知道以后怎样过", "after": "你允许旧友看见迷惘，情分也不必始终建立在谁都很强之上。", "trait": "trust"}, {"text": "问他真有何事还想做", "after": "你不只害怕失去一个伴，也认真关心他自己的人生还有什么愿望。", "trait": "care"}]}], "43": [{"title": "半夜误认的鼓声", "body": "潮声骤起，鲁智深提起禅杖便走，以为战事又到。众僧说明是钱塘潮信，他才停下来听。你看着那熟悉的背影，发现有些战场离开了，身子里却仍会留下随时要再赴险的准备。你自己又何尝不是如此。江水按时而来，没有哪位敌将藏在其中，也不需要谁以性命去赢它。", "spoken": "僧人：这声响日日两回，不曾失信。", "choices": [{"text": "将兵卒误惊的消息安抚下来", "after": "你知道营中来的许多人都会被这声音牵动，不只笑一位朋友听错。", "trait": "care"}, {"text": "把禅杖稳稳放回原处", "after": "你用一个平常动作说明此刻确实不必再战。", "trait": "restraint"}, {"text": "跟着走到窗边听完一阵", "after": "你不急着替朋友解释什么，只陪他把这一回潮声真正听清。", "trait": "trust"}]}, {"title": "洗浴之后", "body": "鲁智深请人烧水、取净衣，神色忽然安稳。你想问他为何，又被那份少见的从容挡住了一瞬。他将几句要交代的话说给众人，并不讨价还价地向谁求一个保证。你不能把他的归宿当成自己选择的奖赏或惩罚，也不能因为不愿失去，便不肯听完朋友最后想说的话。你坐近些，知道陪伴有时只能做到不先逃开。", "spoken": "鲁智深：烦劳诸位，替洒家将这些安排妥当。", "choices": [{"text": "认真听完他的交代", "after": "你把朋友自己的愿望放在自己的舍不得之前，记住要送到何处的物件。", "trait": "oath"}, {"text": "陪在近处，不逼他再谈战功", "after": "这一刻他不必替任何人的故事作结，只是你认识许久的那个人。", "trait": "care"}, {"text": "替他挡去无谓围观", "after": "你保护朋友最后的安静，不让一份哀伤也变成人人看热闹的场面。", "trait": "restraint"}]}, {"title": "天明时的空处", "body": "天明后，鲁智深已经安坐不动。来的人很多，说的话也多，有的谈佛性，有的谈封赠。你都听见，却仍觉得桌边那一处本该放着热饭。你不是没有见过死人，只是每回见到熟悉的人，过去所有关于必须坚强的道理都会重新变得不足。你可以哭，可以沉默，也可以去做朋友托付的事；不必先装作自己已经看开，才配好好送他。", "spoken": "心声：我还活着，不是就该立刻不难过。", "choices": [{"text": "先照朋友的嘱托办后事", "after": "你用尚能做的事接住悲伤，不让它只能化作下一场怒火。", "trait": "oath"}, {"text": "陪同样难过的人坐一会", "after": "你没有将哀伤据为自己一人的事，同行的人也得了一处能停下的地方。", "trait": "care"}, {"text": "到江边走过一圈再回来", "after": "你给自己一点喘息，仍愿回来面对这场真实的失去。", "trait": "freedom"}]}], "44": [{"title": "宋江带来的封赏话", "body": "宋江来时，衣上仍带军中的尘。他先看你的伤，再说将回京论功。你知道他的好意，也知道自己并非必须以受赏证明这一生的苦没有白受。可是谢绝以后做什么，同样不能只交给一句清静。你可以留下照看病人，可以以经验继续教军，也可能在远方找一个不再为旧名所困的地方。你要回答的是余生，不只是一次朝觐。", "spoken": "宋江：你若实在不愿，我便照实写入册中。", "choices": [{"text": "先提出照护与退役的安排", "after": "你将自己的去留与仍在病中的人一并考虑，不只求一个人的自在。", "trait": "care"}, {"text": "询问能否改任授武而不再冲阵", "after": "你不假装伤势不在，也不认为本事只剩下拼命一种用法。", "trait": "duty"}, {"text": "请他准许自行远行", "after": "你开始认真争取不再被任何一张调令随意召回的日子。", "trait": "freedom"}]}, {"title": "不欠功名的一条命", "body": "军吏讲到封赠时，常说若放弃太可惜，像一条伤命只有换成官名才算讨回。你望着空袖，不觉得它能被任何名目接好，也不愿别人替你把选择说成不识抬举。你当然可以收下应得的钱，可以选择一份仍能做的事；但接受与谢绝都应该是你自己愿意，不是因为已经受过苦，往后便必须继续沿同一条路偿还。", "spoken": "心声：我不是一生受过伤，就一生都得替那伤找个大名号。", "choices": [{"text": "收下该有的归凭，拒绝空衔", "after": "你分清生活所需与虚荣，不必以全不接受才能证明自己清醒。", "trait": "restraint"}, {"text": "把教学所需与职责问清", "after": "若继续任事，也须有你肯承担、确实做得到的内容。", "trait": "duty"}, {"text": "保住随时离任的条件", "after": "你愿意帮人，却不再把余生一次签给看不见的将来。", "trait": "freedom"}]}, {"title": "走的人与留的人", "body": "离京或入京的名单分开后，营里忽然有些生分。有人以为留下是对宋江不满，有人认为远行就是只顾自己。你见过同一张桌如何因招安分歧变得难坐，不愿临到散场还只会用两种好坏替人分类。你要的是有朋友仍然愿意承认彼此，即使那个人最后选了与你不同的日子。", "spoken": "旧卒：二郎若不一同走，还算咱们的人么？", "choices": [{"text": "明言去留不同也可互相照看", "after": "你不将忠义系在同一条路上，朋友以后仍可以敲开你的门。", "trait": "oath"}, {"text": "为各处留下可以寄信的地址", "after": "情分有了具体去处，不只是散席前一句常来常往。", "trait": "trust"}, {"text": "尊重不再愿谈军中往事的人", "after": "你不强迫别人一生只活在与你共有的那一段里。", "trait": "freedom"}]}], "45": [{"title": "病榻前的一碗水", "body": "林冲的病使他说话断续，常常一句话到一半便得停。你从前见他提枪时稳得像山，如今才知再有本领的人也会有连端碗都需别人等的时刻。照顾不像打仗，没有一声号令以后便能立刻见输赢。有时你等了半日，他只是多喝几口水；这份没有喝彩的工夫，仍然能分出你愿不愿意把别人当作完整的活人。", "spoken": "林冲：二郎，又劳你在这里守着。", "choices": [{"text": "让他说完，不替他急着作答", "after": "你把时间让给病中的朋友，他仍有权决定自己想说什么。", "trait": "care"}, {"text": "把护理轮次安排下去", "after": "你不愿只有熟人在场时才有人被照看，日子须能真正接续。", "trait": "duty"}, {"text": "请他留下想托付的书信", "after": "你不替他预言结局，只给尚能说出的愿望找一个送到的办法。", "trait": "oath"}]}, {"title": "谈到东京的时候", "body": "林冲说到东京，眼神短暂明亮，接着又避开某个名字。你知道他有许多话不能只用报仇来填平。若你此刻大声答应替他杀尽旧敌，听来很像义气，也可能逼他在生命最弱的时候还要继续为恩仇想下去。你在病榻旁第一次认真学着不急于提出一个办法，只问他自己究竟最想留下哪件事。", "spoken": "林冲：有的地方，怕是回不去了。", "choices": [{"text": "听他讲旧日家常", "after": "你允许一位教头不只以冤屈被记住，他也曾有过真实而寻常的快乐。", "trait": "care"}, {"text": "答应护送受伤同袍返乡", "after": "你向病中的同袍应下归途，不让照顾只停留在病榻前的一句安慰。", "trait": "oath"}, {"text": "不许旁人以为病人听不见便议论", "after": "你护住的是仍坐在这张榻上的人，而不只提前安排他的身后。", "trait": "mercy"}]}, {"title": "不该被催快的送别", "body": "林冲终究没能再上路。寺中多了一次需要清理的床铺，也多了几样无人再来领的物件。你知道自己不能将所有故友都留下，却仍会在夜里问是不是还能早一点做什么。没有人能给你一个使这份失去完全合算的解释。你能做的，是不把遗愿办得潦草，不让后来仍病着的人只因为结局难看便再无人愿靠近。", "spoken": "心声：送过朋友，也不能因此不再肯与人相交。", "choices": [{"text": "将遗物与愿望分别送到", "after": "你没有以忙乱作理由，让一封该交到人手里的信永远压在柜底。", "trait": "oath"}, {"text": "留下护送余下病卒", "after": "你不因救不回所有人，便拒绝为还能活下去的人做事。", "trait": "care"}, {"text": "想清余生究竟要往哪里去", "after": "悲伤不能替你决定一切，但你也不再假装自己能够永远停在这一夜。", "trait": "freedom"}]}], "46": [{"title": "灯下的几样旧物", "body": "你摊开还能留下的东西：一截断棒、一份供词、一页军籍、一串数珠。不是每样都还完整，有些只剩记忆能认出它们怎样来。它们可以变成一套供旁人讲述英雄的道具，也可以提醒你自己：最重要的改变常不是打赢，而是有没有护住一个人、守住一句答应。你得决定余生要接住其中哪一条线，而不是只将它们封进过去。", "spoken": "心声：我不能改尽来路，却仍能为下一日负责。", "choices": [{"text": "整理还可兑现的照护承诺", "after": "你将人名从纪念里重新取出，余生可以成为实际有人受益的日子。", "trait": "care"}, {"text": "留出可传给后人的技艺记录", "after": "你愿意让自己的经验不只伴随一把刀消失。", "trait": "duty"}, {"text": "把能带走的东西收成小包", "after": "你为远行作的是可行准备，不再只在难过时说想离开一切。", "trait": "freedom"}]}, {"title": "没有完成的名单", "body": "仍有人病着，仍有人找不到归途，也仍有仇人的名字会让你难以安坐。你不可能把三张名单都办到最后一笔才开始生活。你可以选一份愿意长久承担的责任，也可以承认自己需要离开；但若一味把所有未完都当作必须再杀一场的理由，便永远不会有哪一天允许自己回家。", "spoken": "旁白：你反复做过的选择，已经在为余生留下门槛。", "choices": [{"text": "优先安排无力自行归家的人", "after": "你将义气落在没有战功可夸的一程护送上。", "trait": "oath"}, {"text": "把愤怒写清，却不急着追去", "after": "你承认它仍在，仍愿意让下一步经过自己的判断。", "trait": "restraint"}, {"text": "寻找同路的船与可靠接应", "after": "远方不再是一句空的逃离，而是一条有出处、有人认得的路。", "trait": "freedom"}]}, {"title": "一封没有催你的信", "body": "有人送来旧友的信，纸上没有请你立功，也没有问伤好以后还能杀多少敌。只是说那里有一处住得下的屋，若愿意，来时可捎信。你将它读了两遍，发觉自己许久没有收到过不带要求的邀请。无论是故乡、寺院、边关还是江海，真正使人能停下的，或许正是这种不必先证明有用才配进门的地方。", "spoken": "信里写：来不来都好，平安便好。", "choices": [{"text": "认真回一封自己的打算", "after": "你不再让挂念的人只从传闻里知道自己是否还在。", "trait": "trust"}, {"text": "保留一个随时能回来的地址", "after": "选择远方也不必烧尽旧路，独立与情分可以同在。", "trait": "freedom"}, {"text": "告诉对方自己还愿帮人做什么", "after": "你没有把受伤当成全部身份，也不再夸下超出本事的诺言。", "trait": "duty"}]}], "47": [{"title": "最后一次巡过院门", "body": "院门、江岸、渡口与远处道路都还在。过去你总觉得只要走得够快，就能追上一个失去的人、一份迟到的公道。如今你终于知道有些追赶不会因再赶一日便不同，余生也不能永远等所有账都平了才开始。你回看自己一直护着什么，也看见自己曾将什么丢在身后。这次不再是旁人派你上路，而是你自己要认领将走的路。", "spoken": "心声：往后不再靠是谁催我，便说自己没有别的选择。", "choices": [{"text": "看清自己仍能承担的日常", "after": "你愿意让英雄以后还有买米、写信、帮人开门的寻常岁月。", "trait": "care"}, {"text": "将该交代的责任交到人手", "after": "你不逃避未完的事，也不认为它们只能永远由你独担。", "trait": "duty"}, {"text": "为选定的去处真正启程", "after": "你不再把自由留作心里一个永不到来的以后。", "trait": "freedom"}]}, {"title": "还能收回的刀", "body": "刀还在。它曾替你活命，替你报仇，也曾让你几乎只剩下别人害怕的样子。你不用假装从此不再生气，才算能够放下它；真正的界限是在下一次愤怒到来时，仍知道谁不该受伤、哪一笔不该再讨。你用右手摸过鞘口，觉得这一回收起的不是一件失去用处的兵器，而是自己终于有权不再使用它的余地。", "spoken": "心声：刀归鞘，不是这一生便白走了。", "choices": [{"text": "记住曾救你的每一个具体姓名", "after": "你不让世界只由仇人的名单组成，活人仍占有自己的位置。", "trait": "oath"}, {"text": "承认还有遗憾，不再求全胜", "after": "你放下的是必须抹平所有损失的执念，不是对故友的记忆。", "trait": "restraint"}, {"text": "把教人的第一句话重新想好", "after": "若余生还要传本领，你愿先传何时不该动手。", "trait": "duty"}]}, {"title": "此生由你落款", "body": "这一生已经走过太多由别人书写的称呼：病客、壮士、都头、配军、行者、头领。它们都不是假的，却没有一个足以替你说尽全部。最终归宿会承接一路真正做过的事，不会因为末尾一句漂亮话便忽然改写。你仍有最后一点可以决定的东西：怎样面对这条已被自己铺出的路，怎样将余下的岁月或最后的一次承担，认真走完。", "spoken": "终卷：结局会交代此后的人生，故事不再留给续作。", "choices": [{"text": "把余生交给仍可照看的人", "after": "你没有忘记来处，也不再只为过去而活。", "trait": "care"}, {"text": "让这身本事留下护人的用处", "after": "你愿意有责任，却不愿再任人把性命当作无穷无尽的资源。", "trait": "duty"}, {"text": "认领自己已选定的自由", "after": "你不再等谁发给一个许可，才肯开始自己的最后一段路。", "trait": "freedom"}]}], "36": [{"title": "夜哨的名字", "body": "北地的风把旗角冻硬，你巡到最后一处时，一个新卒仍不肯换班。他说自己不累，手却几乎握不住枪。你见惯了人怎样因为怕被说怯弱而逞强，也见过旁人只需一声壮士便使自己走进险处。现在你能决定这句话是否还会落到别人身上。兵卒的警醒不能只靠怕挨罚，更不能靠一双已经失去知觉的手。", "spoken": "新卒：头领别把我记成畏寒，家里知道要丢脸。", "choices": [{"text": "先说寒冷不是罪", "after": "你替他说出不敢说的话，其他守夜人也终于敢照实报出疲累。", "trait": "mercy"}, {"text": "重排换班，不只换这一个", "after": "关怀不再只能等头领恰好走过，明夜也有能照办的次序。", "trait": "duty"}, {"text": "教他辨认自己将要失力的征兆", "after": "你将经验留给人，而不是只让他背下一个再撑一会的命令。", "trait": "skill"}]}, {"title": "营火边的家乡话", "body": "轮下来的兵卒围火坐下，口音混在一起，听得你忽然想起阳谷街口。有人说起家中田地，有人却连家里如今住在哪儿都不清楚。你从前在柴庄以为远行只需一条敢走的腿，如今见了这么多人，才知离乡的代价不会同样显在脸上。一个人能不能安心守夜，也与他是不是相信自己倒下以后仍会有人知道姓名有关。", "spoken": "老兵：若回得去，便先修那间漏雨的屋。", "choices": [{"text": "让大家互记同乡的联络处", "after": "你们为失散与伤病留一条路，不只在战前互称一声兄弟。", "trait": "oath"}, {"text": "不催他们立刻停下闲话", "after": "这片刻不是散漫，活人谈起要回去的地方，才更知道何以不能轻死。", "trait": "mercy"}, {"text": "把缺冬衣的队数查明", "after": "你不让温暖只留在火堆旁一段好听的感慨里。", "trait": "duty"}]}, {"title": "远处的号角", "body": "敌情未到，前哨已传来几种说法。一支队伍若把每个传闻都当实情，很快就会被自己的奔走耗空；若全不理会，又可能真在最迟的一次失去反应的余地。你将守夜者叫到图前，请他们只说眼见多少火、听到几次号，不要先替那些声音起一个吓人的名字。", "spoken": "前哨：小的看不真切，只知比昨夜亮了许多。", "choices": [{"text": "分清实见与推断再报", "after": "你没有责怪看不见的人，反使下一次报讯更可靠。", "trait": "insight"}, {"text": "保留预备队，不全数惊起", "after": "警惕也要给人留恢复的可能，不能夜夜只靠一口硬气。", "trait": "duty"}, {"text": "亲查最接近村民的一段路", "after": "你不只顾营内安稳，也防两军的误会先烧到没有军令的人家。", "trait": "mercy"}]}], "37": [{"title": "胜仗之后的门", "body": "破阵以后，村里的门仍然闭着。百姓听过太多先说秋毫无犯、随后便要粮要车的军队，不能因为你自认不同就立刻相信。你站在门外，听见屋中有人搬动重物，也有人低声哭。你没有一整天可以等，却知道若只拿军令催开，这支队伍与他们害怕的东西便再无分别。你须在急行与不使恐惧继续扩大的办法间找一条可走的路。", "spoken": "村人：粮真没剩多少，莫再取了。", "choices": [{"text": "先说清只求什么、不取什么", "after": "具体的边界比一声自称义军更能让人判断可否开门。", "trait": "insight"}, {"text": "将军粮分一点给伤民", "after": "你不用别人的饥饿替自己赢一份仁义名声，先拿出自己的一份代价。", "trait": "mercy"}, {"text": "安排队伍绕开民居歇脚", "after": "你不逼百姓用接待持械者来证明自己愿意合作。", "trait": "restraint"}]}, {"title": "慢下来的人", "body": "队伍要走，一位老人却从屋里被扶出来，说家中还有走不动的。传令者催你，若误了会合便要担责。你并不是第一次在快慢之间选择，只是如今每一张催行的令纸都更有分量。你可以让少数人留下，也可以替他们找接应，但不能用一个无人负责的会有人来，把自己眼前的两难推给一条已经荒冷的街。", "spoken": "传令者：再留，就不是一句军情紧急能解释的了。", "choices": [{"text": "指定救护队与会合时辰", "after": "你不将安置留成空话，去留都有人知道对方在哪里。", "trait": "duty"}, {"text": "自己护送最难移动的一段", "after": "你不只让部下为自己的仁义多担差，先拿自己的行程承担。", "trait": "mercy"}, {"text": "请村人决定愿往哪处安顿", "after": "帮人离开，不等于可以替他抹去家乡与选择。", "trait": "freedom"}]}, {"title": "记功的人没看见", "body": "后来报功时，这段停留没有被写进去，反有人提醒你行军不够迅速。你并不需要每件照看人的事都换赏银，可若连解释都不愿听，下一位头领便更难选择同样的做法。你看着报告上整齐的杀获与夺取，知道一个制度怎样记事，就会慢慢教人把什么当作值得做的事。你决定是否还要为几个已经安顿的村民多说一句。", "spoken": "同僚：事已过了，何苦再争一个名目。", "choices": [{"text": "把救护经过作为公事补录", "after": "你不只为自己分辩，也为以后愿这样做的人留一个可以援引的先例。", "trait": "duty"}, {"text": "不拿村民来作讨赏的凭证", "after": "你保留事实，却不再将受救的人折作自己的功劳筹码。", "trait": "restraint"}, {"text": "将伤民托付的回信送完", "after": "无论功册如何写，已经应下的事仍得有人真正去办。", "trait": "oath"}]}], "38": [{"title": "山上的旧话", "body": "五台山的钟声使军中喧嚣暂时退开。鲁智深说起师父从前的话，语气不同于议事堂里。他并非突然不肯帮弟兄，只是已经走了太久，想知道一个人若不再上阵，是不是仍算活得有用。你也被这个问题问住：自己若放下刀，还剩下什么能与人相处，是否只会坐着等别人再讲起那只虎？", "spoken": "鲁智深：人总有不必再打的时候罢。", "choices": [{"text": "认真问他想去何处安歇", "after": "你不把朋友的疲倦听成酒后闲话，他终于肯说出心里最小的愿望。", "trait": "care"}, {"text": "承认自己也没想过停下来", "after": "你们不再只以强者的样子相见，谈起脆弱反而更像朋友。", "trait": "trust"}, {"text": "请教伤残以后还能做什么", "after": "你先为可能失去的东西留一份心理余地，不等事到眼前才只剩不肯。", "trait": "duty"}]}, {"title": "不以封赏作答", "body": "有人说功成后自然有封赏，何必现在想清净处。鲁智深笑了笑，没有再争。你知道这不只是喜欢住哪座寺：若每一次想离开都被解释成还没得到足够的赏，人便永远不能真正说自己已经够了。你想起回乡的愿望，也想起从前收下好饭后越发难开口拒绝的日子。", "spoken": "心声：一条退路，不该非得等人拿更大的好处来批准。", "choices": [{"text": "支持功成后自行去留", "after": "你替朋友保住不再争赏的权利，也替自己留住同样一扇门。", "trait": "freedom"}, {"text": "商量用一部分钱安置伤病", "after": "你不只想个人怎样离开，也想不能自行赶路的人怎么退下。", "trait": "care"}, {"text": "约定离军后仍互通消息", "after": "离开同一支队伍，不必等于从此彼此失散。", "trait": "oath"}]}, {"title": "一只收好的酒碗", "body": "下山前，你看见鲁智深将用过的碗洗净放回，并没有摆出看破一切的样子。他依旧会饿，会笑，会因为兵卒少吃一口而发火。你这才明白清静未必是离人很远，也可能是仍肯做眼前小事，却不再被一个必须证明自己的名字驱赶。你将这景象记住，知道日后若遇见更难的一关，自己或许需要的就是这样一幅普通图景。", "spoken": "鲁智深：走罢，山下还有人等饭。", "choices": [{"text": "帮他将给伤卒的干粮分开", "after": "你们的交谈没有停在道理，仍回到还有谁需要照看。", "trait": "care"}, {"text": "把归途的约定写在小册上", "after": "你不让承诺只在钟声里显得好听，日后仍可翻出提醒自己。", "trait": "oath"}, {"text": "不再追问何时能得更多功名", "after": "你将一点注意力从远处的封赏取回，落在脚下这段真实的路。", "trait": "freedom"}]}], "39": [{"title": "水边报来的名字", "body": "张顺的消息传来，营里先说他立了大功，随后才承认再也回不来。有人讲得仿佛成神能补齐一个人的死，你却记得水军头领湿着头发说笑时的样子。名册上有再好看的封赠，也不能使那个人重新坐到饭桌前。你想做点什么，却又知道悲痛最容易被人变成催你再向前冲的口号。", "spoken": "军卒：为张头领报仇，便是最好的祭奠。", "choices": [{"text": "先寻找同路失散的人", "after": "你把对死者的念想先用来护住可能还活着的人，而不急着再添一笔死伤。", "trait": "care"}, {"text": "将确知与传闻分开记", "after": "你不让一个已经不能开口的人，被随意添上谁都爱听的传奇。", "trait": "insight"}, {"text": "允许部下为他停一刻", "after": "你不拿军情紧急否定人的哀伤，队伍也不必只会麻木往前。", "trait": "mercy"}]}, {"title": "空船还在", "body": "水军拖回一只空船，绳缆上仍有新水。有人忙着重新配人，有人站在旁边许久不动。你看见一个年轻兵卒想收起旧主人的私物，又怕被算作偷取。物件太少，却都牵着一个人怎样活过。你在炮声外的短暂停顿里，学着把这些事当作军务：因为若无人照管，最先遗失的就是那些没有写进战功的人。", "spoken": "兵卒：这小包裹，该往哪里送？", "choices": [{"text": "查清他生前托付给谁", "after": "你不让遗物只成下一位接手者的方便，而尽力回到该去的手里。", "trait": "oath"}, {"text": "给清点遗物设见证", "after": "你保护物件，也保护那个愿意帮忙却最容易被误会的年轻人。", "trait": "duty"}, {"text": "将可用军械与私物分开", "after": "队伍可以继续作战，一个人的生活却不该因此被全部混入公库。", "trait": "insight"}]}, {"title": "不肯点头的请战", "body": "听完消息，有人来求第一批攻城，说若不让去便是看轻。你在他们脸上认出自己也有过的神情：只有立刻再冒一次险，才像不曾被刚才的失去压倒。你不能嘲笑这种痛，也不能为了让大家觉得自己够义气，便把一队急着赴死的人领向城门。拦住他们，意味着你也得承担不够痛快的目光。", "spoken": "军卒：头领，你难道咽得下这口气？", "choices": [{"text": "说明不拿同袍的命抵自己的痛", "after": "你没有否定报仇的心，却不许它自动成为送更多人去死的理由。", "trait": "care"}, {"text": "重排侦察与攻守次序", "after": "你让行动重新依据敌情，而不是依据谁的哭声或喊声最响。", "trait": "duty"}, {"text": "亲自陪最难过的人守一班夜", "after": "你不只说一句冷静，愿意花时间陪他熬过不能马上填平的那一块。", "trait": "trust"}]}], "40": [{"title": "山路上的纸符", "body": "乌龙岭一带传来包道乙施法的说法，兵卒越传越神。你不必假装全然不信，却也不能让一阵传闻先打散队形。眼前的山势、暗处的敌手、伤兵能退向哪一道口，都比争论对方究竟算不算妖术更需要马上有人看清。你摸到戒刀，知道再厉害的一把刀也不能替所有人的眼与脚一起作主。", "spoken": "前哨：有人说那剑会自己飞来。", "choices": [{"text": "把退路先交代给各队", "after": "你在出手以前先想怎样带人回来，不让败退全凭一声各自逃命。", "trait": "duty"}, {"text": "观察敌方施为的先后", "after": "你不让未知自动变成无所不能，先找仍可辨认的规律。", "trait": "insight"}, {"text": "与近旁同伴约定互相照应", "after": "你承认自己也可能失手，这个约定便不只是头领对小卒说的客套。", "trait": "oath"}]}, {"title": "来不及的一瞬", "body": "战阵中的变故不是练习时留给人慢慢选择的破绽。你听见呼喊，视线里一线寒光已经越过前方。很多年后回想，也未必能找出一个只要换一步便必定无伤的答案。真正还能由你决定的，是伤势落下之后要不要接受帮助，要不要为了不肯认输再叫几个人跟着你一起陷进去。", "spoken": "交锋：能让同伴拉住你，也是一种本事。", "choices": [{"text": "听见退令便回应", "after": "你让来援的人知道自己仍清醒，不必在混乱中同时猜测你的去向。", "trait": "care"}, {"text": "护住身侧的同伴再后退", "after": "你没有盲目转身，将能避开的第二道危险让过去。", "trait": "skill"}, {"text": "先压住伤处，不再追击", "after": "你把活下去放在继续证明自己的前面，承认这一仗不能靠硬撑赢回。", "trait": "restraint"}]}, {"title": "有人接住了刀", "body": "跌回阵后时，你先找刀，旁人却按住你，让医者近前。你能听见外头还有战声，身体却不再肯照平日的念头动。被人扶着不像你想象中那样体面，也没有立刻带来安稳；你必须把一部分命交给身边这些人，承认此刻自己最有用的事也许正是少挣一次、少发一句火。", "spoken": "同伴：刀在这里，人先别再动！", "choices": [{"text": "将撤出路线说清", "after": "你用尚能说出的经验帮助后来者，而不是只盯着自己失去的东西。", "trait": "duty"}, {"text": "谢过将你带回的人", "after": "你叫得出他的姓名，让相救不只是一句许多无名者做过的事。", "trait": "oath"}, {"text": "允许自己暂时无能为力", "after": "你不因还不能站起来就责怪所有人，给身子留下真正恢复的余地。", "trait": "restraint"}]}], "41": [{"title": "一只系不上的衣扣", "body": "清晨醒来，你下意识伸手，才在一瞬之后重新记起空了什么。身边的人赶紧来帮，你却险些将好意推开。打虎、破枷、挥刀，都没教你怎样一只手系好一根细带。你知道这不是一场靠多练几次就能把过去全部练回来的比试；若余生只剩与空袖较劲，活下来的时间也会被另一种战场吞去。", "spoken": "医者：先让人帮这一回，不会因此便永远站不起来。", "choices": [{"text": "接受帮助，再学新的办法", "after": "你不将求助与失去尊严绑在一起，日常终于有了可以重学的开头。", "trait": "care"}, {"text": "试着自己完成一件小事", "after": "你不急着重演昔日的全部本事，先取回手边一个确实做得到的动作。", "trait": "skill"}, {"text": "告诉旁人何处不愿被碰", "after": "你可以接受照顾，也仍有权决定怎样被对待。", "trait": "restraint"}]}, {"title": "不能再照旧的军册", "body": "军中有人来问伤势，话里很快转到还能否任原职。你一时很想说能，像只要答得够坚决，空袖便不至于成为别人看你时先看见的东西。但你也知道部下的命不能用来替自己的不甘作保证。你仍有经验，仍能辨阵、教步、记得每个需要照看的人，只是这些未必还要以冲在最前的样子出现。", "spoken": "军吏：若需另列安置，今日便得写上。", "choices": [{"text": "照实登记，不隐瞒所需照护", "after": "你让制度有机会看见真实处境，不再拿自己当作永远不会坏的兵器。", "trait": "duty"}, {"text": "提出能教人的职分", "after": "你没有把一生本事全系在失去的左臂上，仍想找可以护人的去处。", "trait": "duty"}, {"text": "请求离军休养的余地", "after": "你知道这不是逃避一场未完的仗，而是替余生留一点不再被征用的权利。", "trait": "freedom"}]}, {"title": "胜报传到病榻", "body": "鲁智深擒住方腊的消息到了。有人来贺，你知道同伴完成了艰难的事，也替活下来的人松一口气；随后却又觉得自己似乎不知该放在哪里。若只因受伤便不敢听胜报，未免对朋友太苛；若必须跟着欢喜得像从未失去，又实在勉强。你终于发现痛与庆幸可以同在一副身子里，不必将其中一个赶尽才能面对别人。", "spoken": "传讯者：战事总算快到头了。", "choices": [{"text": "真心祝贺朋友，也承认自己疼", "after": "你不让两种真实互相作假，旁人也终于知道该怎样与你说话。", "trait": "trust"}, {"text": "问回来的队伍还缺谁", "after": "你没有让一封捷报盖掉尚未归营的人名。", "trait": "oath"}, {"text": "先不谈封赏，只谈休养", "after": "你给自己留一段不必立刻证明仍有价值的日子。", "trait": "restraint"}]}]}, "retreat": {"36": [{"title": "家书不是军令", "body": "信被转了几道，纸角已经磨软。哥哥没有催你立功，也没有先问能不能升官，只说近来蒸笼修好了，清早做饼总比从前快些。你读到这里，忽然不能像读战报那样立刻放下。一个活着的人写来的普通日常，比许多声大捷更像你一路想保住的东西。你将信放在桌上，等鲁智深读完，才说起弟兄们也该有这样一天。", "spoken": "鲁智深：有门等着你，便莫再当作没有归处。", "choices": [{"text": "把活着回去当作真正目标", "after": "你不再等一个更大的功劳才肯承认，平安本身值得认真筹划。", "trait": "care"}, {"text": "抄下仍可转信的接应处", "after": "你把思念变成退路，故乡终于不只在心里。", "trait": "insight"}, {"text": "问旧友各自想去哪儿", "after": "你没有以自己的家为所有人的归处，容许每个人说出不同愿望。", "trait": "freedom"}]}, {"title": "一张不写军功的纸", "body": "你重新铺纸，最先写的不是破过哪座城，而是谁伤了、谁有老亲、谁已经不想再打。宋江起初不解，鲁智深却先把自己的名字写在想歇一歇的人旁边。一个头领肯先承认疲倦，小卒才敢把同样的话说出口。你看着名单渐长，知道此前没有人说，并不等于人人都愿意继续。", "spoken": "军卒：真能选，不会往后再算怯战么？", "choices": [{"text": "明说不会因求退受辱", "after": "你们为选择立下见证，不让它在下一道军令来时又被悄悄收回。", "trait": "duty"}, {"text": "将可以继续任事的人另列", "after": "退路不是全军一夜散尽，你认真为去与留各找承担。", "trait": "insight"}, {"text": "让姓名由本人确认", "after": "你不替沉默者作主，也不让队正为图省事替一队人全都答应。", "trait": "freedom"}]}, {"title": "不再只劝忍一忍", "body": "有人说等打完下一仗便好，你请他说出下一仗之后还有没有再下一仗。不是每一个提议继续的人都怀着恶意，可若安顿永远放在最末，活人便只能一层层少下去。你并不要求大家立刻与你想得一样，只要求退役与照顾的事从今日起有经办、有时辰、有能拿出来追问的凭据。", "spoken": "你说：别叫所有后路，都活在等以后这三个字里。", "choices": [{"text": "订下首批安置的日期", "after": "你们终于有一件可以检验有没有做到的事。", "trait": "duty"}, {"text": "先办理最重的伤病", "after": "没有战功可以夸的人，也不必永远排在名单最末。", "trait": "care"}, {"text": "把商议结果交各队留底", "after": "口头答应不再只由头领记着，受影响的人也能拿在自己手里。", "trait": "insight"}]}], "37": [{"title": "林冲不必再逞强", "body": "林冲说自己还走得动，说完却扶了一下椅背。你没有拆穿来使他难堪，只将册中的旧病与如今需要面对的路摆给他看。你们不再等人倒在阵前才承认受伤，这使他久违地沉默了很久。被允许退下，不是被同伴舍弃；只是一个再能打的人，也终该有不被本事驱赶的日子。", "spoken": "林冲：若大家真有安排，我便不再硬撑这一程。", "choices": [{"text": "让他亲自选择安歇处", "after": "你照顾朋友，也尊重他仍能决定自己的生活。", "trait": "care"}, {"text": "请医者提早照看，不等恶化", "after": "你把机会用在事情尚可改变的时候，而不只在悲剧后追问若当初。", "trait": "duty"}, {"text": "找可靠同伴一路相随", "after": "安置不止是一张准许离营的纸，还要有人走完中间的路。", "trait": "oath"}]}, {"title": "施恩的心结", "body": "施恩总觉得欠你太多，听说退下便想再替你做一件大事。他以为多冒一次险才算还清，正像你曾以为吃过他的饭便须替他赢回一切。你如今听出了这条相同的绳：若恩情永远只能以更大的危险偿还，朋友便谁也不能先安稳下来。你要替这份交情换一个往后还能过日子的算法。", "spoken": "施恩：总不能每回都是哥哥护我。", "choices": [{"text": "请他帮着经营归途补给", "after": "你让朋友在能长久承担的地方出力，不必总拿命证明情分。", "trait": "care"}, {"text": "说明不必把恩债算到一命换一命", "after": "你们都松了一口气，交情终于不再只是一张不断加重的账。", "trait": "restraint"}, {"text": "请他替弱者留些安家钱", "after": "他把感激传给仍有需要的人，也不必永远只朝你一人还债。", "trait": "mercy"}]}, {"title": "第一批车马", "body": "车上坐的不全是名震江湖的头领，更多是没有人会替他们写传的小卒。你看见有人反复摸归凭，怕走出营门便有人说不算。你命接应者与他对清姓名，再交到下一站的人手里。省去这几步也许眼前无事，却会将路上的风险全部留给最难为自己解释的人。你宁肯多等片刻，也不让这份新规从第一程就落空。", "spoken": "伤卒：到了前头，真有人认这张纸？", "choices": [{"text": "亲送第一队完成交接", "after": "你不是只在帐里签准，让人实际看见路确实接得上。", "trait": "duty"}, {"text": "让同乡尽量一同归去", "after": "一条路上能叫出彼此姓名的人，比一张写得再好的纸也多一份照应。", "trait": "oath"}, {"text": "留下途中遇阻可求援的地方", "after": "你们不以送出营门为安置完毕，承认归途也属于承诺。", "trait": "insight"}]}], "38": [{"title": "对宋江说实话", "body": "你与宋江不是第一次谈去留，今日却带着已办成的安置与愿意归家的名单。他不能再只说这是你一时不满，也不得不看见自己所想的前程与很多人的盼望并不完全相同。你仍记得当初送你远行的人情，正因记得，才更不愿眼看这位旧友只向一条越来越险的路走去。", "spoken": "宋江：若不再领军，弟兄们多年辛苦又算什么？", "choices": [{"text": "指给他看已经平安上路的人", "after": "你不用空话否定他的苦心，只让他看见苦心也能有别的成果。", "trait": "care"}, {"text": "请他想一想不做先锋的自己", "after": "你不把朋友只当作能带兵的人，也容他为自己留一份普通人生。", "trait": "freedom"}, {"text": "将功劳与退隐的凭据一并讲清", "after": "你不是叫人白白舍去应得之物，而是替功成以后真正能退找条件。", "trait": "duty"}]}, {"title": "那杯没有饮的酒", "body": "封赏使者来请，席上话讲得周全，却对今后任所与约束答得含糊。宋江望你一眼，终于没有立刻以受恩为重，将酒一饮而尽。你不敢说每一杯恩酒都藏恶意，只是知道有些决定一旦用一杯酒做成礼，后来便更难说自己还要想想。你们先留纸，再议事，不让热闹替余生落款。", "spoken": "你说：酒可稍后喝，人的去处先讲明白。", "choices": [{"text": "封存来酒，先审文书", "after": "一份谨慎不必等后来出了事才被叫作先见。", "trait": "insight"}, {"text": "说明选择退隐不等于造反", "after": "你为一条不再出兵的路争取正当余地，不让去留只剩服从与敌对。", "trait": "freedom"}, {"text": "请宋江给各头领自行决定的时间", "after": "他终于肯将弟兄两字落实为彼此都能说不。", "trait": "trust"}]}, {"title": "不去那处险任", "body": "宋江重新读了任所与差遣，第一次没有只想着如何使自己配得上这份抬举。他看见旧卒带家书来谢，看见熟悉的人因能退下而真心松快。你没有替他预言一个必然的毒酒结局，只劝他别把与权势的所有信任都放在一句圣恩里。他最终谢绝了会将自己独置于猜忌中的安排，散去旧部，也为故友留住了活着再见的可能。", "spoken": "宋江：既有别的路，何必非将人都赶到一处去。", "choices": [{"text": "帮他将交接办得清楚", "after": "退下不是留一个更大的混乱，名册、钱粮与职责都有去处。", "trait": "duty"}, {"text": "保住各队的联络方式", "after": "从此不再一同列阵的人，仍能在有事时找到旧友。", "trait": "oath"}, {"text": "不要求他从此事事与你相同", "after": "你们能互相救一回，不必先将彼此活成同一个人。", "trait": "restraint"}]}], "39": [{"title": "还没有踏上的死地", "body": "新的征调消息传来，很多人本来以为不必商量便得再去。你们将先前的退役、公差与伤病凭据逐一摆出，终于不是只凭一句不愿再打求情。那些还没来得及发生的失去，并不会自己来感谢你们；你也无须等看见满地伤亡才证明提前准备有用。只要今日能让人少走进一处绝地，便已经值得。", "spoken": "队正：原来前头留这些纸，真能替人挡住一回。", "choices": [{"text": "核对每一队是否同样有归凭", "after": "你不让只有跟在头领近旁的人能走，其余又被仓促编进新阵。", "trait": "duty"}, {"text": "让伤兵先离开军中纷争", "after": "你保护他们的机会，不等每位权贵都对这安排说好。", "trait": "care"}, {"text": "说明不以别人继续作战为羞", "after": "你拒绝拿道德逼同伴选与你一样的路，他们也更愿尊重你的去留。", "trait": "freedom"}]}, {"title": "交还的军械", "body": "军械交接时，有人舍不得，觉得刀枪一离手便再无保障。你同样知道失去依靠的滋味，却也知道若退下仍拖着一支谁都不能查清的私兵，所谓远离猜忌便只剩自己安慰自己。你们保留个人护身所需，将公用军械清点交还，把能长期维持的生活放在一场一触即发的武力争执前面。", "spoken": "杨志：该点清的，点清。省得日后翻一笔糊涂账。", "choices": [{"text": "当面留下双方交接副本", "after": "你用明白的凭据替后来少一场不必再打的争执。", "trait": "insight"}, {"text": "将修械工匠也列入安置", "after": "不拿刀的人同样为这支队伍做过事，不应散场便无人问。", "trait": "mercy"}, {"text": "以身作则交出公物", "after": "你不让收手成为只要求小卒去做、头领却另留一手的规矩。", "trait": "duty"}]}, {"title": "退下也需要勇气", "body": "营中仍有讥笑，说你们终究怕了。你曾为一句怕字上冈，也曾为了不肯显弱几乎将命留在险处。如今这一句再来，你的手仍会紧一下，却不再愿意为让旁人闭嘴，就使已经安顿的朋友重新走回阵里。你看见鲁智深笑着背起包袱，忽然觉得走出营门也可以比冲进敌阵更需要一份坚定。", "spoken": "鲁智深：让他讲去。咱们走咱们的。", "choices": [{"text": "不再以冒险证明不怕", "after": "你守住的不是面子，而是刚替许多人争来的余生。", "trait": "restraint"}, {"text": "提醒队伍按原定路线离开", "after": "你没有让一场嘲讽打乱接应，退路依然稳稳接着。", "trait": "duty"}, {"text": "向仍在营中的旧卒道平安", "after": "不同去处不必成为最后一次的恶言，往后仍有重逢的可能。", "trait": "oath"}]}], "40": [{"title": "完整的两只手", "body": "走到河边时，你用两只手将缆绳拉上船。这个动作从前太寻常，今日却让你想到无数差一点走进去的刀口。你不知道所有未发生的事会是什么模样，却知道这两只手仍能替哥哥搬蒸笼、替朋友端碗。保全不是少活了一段英雄故事，而是多留了许多不必拿来讲传奇的日子。", "spoken": "心声：还能这样用手做事，原来已是很大的好处。", "choices": [{"text": "先帮行动慢的人登船", "after": "你把保全落在眼前，不只为自己平安而庆幸。", "trait": "care"}, {"text": "清点来人，不只点货", "after": "船不因装满了银粮就算可以开，人的姓名仍须一个个对上。", "trait": "oath"}, {"text": "将戒刀妥善入鞘", "after": "你没有丢掉本事，只是不再让它占满每一次与人相见。", "trait": "restraint"}]}, {"title": "孙二娘的包裹", "body": "孙二娘送来旧日替你换装时用过的布，说如今不必再靠藏头避面过路。张青忙着联络接应，仍时不时抬头看你是否真的肯走。你想起这家店曾在最险时开门，许多感谢都还只停在口头。如今回报不必再是替他们杀一个仇人，也可以是让他们从此有一门不靠凶险维持的生意。", "spoken": "孙二娘：这回有盘缠有凭据，堂堂正正走。", "choices": [{"text": "商议往后正经经营的办法", "after": "你把患难之交延伸到能长久活下去的日常。", "trait": "care"}, {"text": "留下可共同照应的住处", "after": "你不让恩人送完最后一程便又消失在自己的故事里。", "trait": "oath"}, {"text": "尊重他们自行选去处", "after": "你想一起安稳，也不拿救命恩情逼朋友陪你走同一条路。", "trait": "freedom"}]}, {"title": "队尾的最后一人", "body": "所有人都说齐了，一个负责牵骡的小卒却迟迟没到。他平时不在最显眼的队伍里，最容易被说作大概先走了。你叫船先等等，果然在后路寻见他正帮一名老人推车。若只看名册数字已足，便会把一个人漏在自己最想避免的空白里。你们等到他回来，船上并没有因此少掉一份胜利。", "spoken": "小卒：小的耽搁了，教大家久等。", "choices": [{"text": "说明不该为被等候而羞愧", "after": "你让他知道自己也是这条归路真正等着的人。", "trait": "mercy"}, {"text": "补上队尾与接应的责任", "after": "好意不能永远靠偶然遇见，你把办法再改清楚一点。", "trait": "duty"}, {"text": "谢过他照顾路上的老人", "after": "你不将自己的同行者看得重要，便否认他也可以为别人停步。", "trait": "care"}]}], "41": [{"title": "归舟上的闲席", "body": "船上第一次摆饭，没有谁急着报下一处战情。鲁智深嫌碗小，林冲慢慢笑起来，施恩提起旧日快活林被你问得哑口无言的账。你们终于能说那些曾经难堪的事，而不立刻担心接下来谁又要死。活着的人会争一口菜，会说错话，会各有烦恼；这些不整齐的日常，恰恰是你最想从命运里抢回的东西。", "spoken": "林冲：这回若要比，只比谁能将饭吃完。", "choices": [{"text": "把酒换作愿喝才饮", "after": "朋友相聚不必再有人为了不显怯就强饮到误事。", "trait": "restraint"}, {"text": "请每人说一件回去想做的小事", "after": "你们有了不靠封赏也能理解的未来，席间笑声比誓言还真切。", "trait": "care"}, {"text": "约定几年后仍可再聚", "after": "你不求永远同船，只求分开以后还愿为彼此留一张凳子。", "trait": "oath"}]}, {"title": "分路的水口", "body": "船行到水口，几位朋友须在此转路。你本想说一起回去多好，话到嘴边又想起自己最不愿受的摆布。有人要拜师，有人要找旧宅，有人还要替家属送一封很久没送到的信。你若真替他们争来了退路，也得接受退路可能通向不同地方。你将地址写明，发觉散席不必都像失去，有时也是终于能各自活下去。", "spoken": "鲁智深：真要来时，写信便认得路。", "choices": [{"text": "互留能确实收到的信处", "after": "你把往后再见从一句客套变成可找到的去处。", "trait": "oath"}, {"text": "分别替难走的人安排接应", "after": "你不因为到了自己的归途，就将朋友余下的那段路全抛在身后。", "trait": "care"}, {"text": "好好告别，不催谁改变打算", "after": "你让自由也属于别人，友情因而不必靠束缚维持。", "trait": "freedom"}]}, {"title": "离家的那条街近了", "body": "还没看见家，先闻见沿路卖饼的香。你忽然怕哥哥认不出自己，又觉得这怕实在没有道理。远处的人忙着平常买卖，没有鼓乐替你宣告回来。你想起离庄时盼着名声，入衙时盼着体面，如今却只想让门里那个常把好饼留给你的人，亲眼知道你确实把自己平安带回来了。", "spoken": "心声：这一趟，不必等人来讲我的事。", "choices": [{"text": "先把刀收好再进街", "after": "你回家的第一步不是叫人看见威风，而是让熟悉的人愿意走近。", "trait": "restraint"}, {"text": "顺手给哥哥挑一件实用物件", "after": "带回去的不只是赏银，还有你终于留意过他怎样过日子。", "trait": "care"}, {"text": "托人告知同路故友已抵达", "after": "你没有一到家就忘了那些也在等你平安消息的人。", "trait": "oath"}]}], "42": [{"title": "门开以前", "body": "院门的木纹同记忆里差不多，门边却添了新钉。你忽然觉得敲这一下比叫阵还难：从前可以想象回来怎样讲一切，真站到这里，倒只剩一句哥哥。门内脚步急起来，蒸笼的盖子被放得太响。你没有再整理衣服，也不必先摆出一个英雄该有的模样，便让那双熟悉的手将你拉了进去。", "spoken": "武大：二哥，你可算回来了。", "choices": [{"text": "先坐下吃热饭", "after": "你不急着证明一路多苦，先接受哥哥此刻真正想给你的照顾。", "trait": "care"}, {"text": "将平安归来的消息说清", "after": "哥哥终于不必从你避重就轻的笑里猜还有没有追兵。", "trait": "trust"}, {"text": "慢慢讲自己以后不再远征", "after": "你把未来交给具体的日子，而不是再留一句不知何时兑现的早些回来。", "trait": "freedom"}]}, {"title": "没有牌位的哥哥", "body": "你看见哥哥在灶边忙，忽然想起自己差一点只能对着一个永不会回答的位置说话。这个念头使眼前普通的动作变得那么珍贵：他会埋怨，会问东问西，会把你不爱吃的也往碗里添。你不必每一刻都感激得郑重其事，只需不再把这份活着的烦琐当作永远不会失去的东西。", "spoken": "武大：怎么只看着，饭凉了还得再热。", "choices": [{"text": "帮他把桌椅摆好", "after": "你用眼前能做到的事回应，不把团聚只停在一句大喜的话里。", "trait": "care"}, {"text": "说出自己曾经有多挂念", "after": "你终于不怕在哥哥面前显得不够强，许多没说完的话有了地方。", "trait": "trust"}, {"text": "听哥哥讲你不在的日子", "after": "他也有自己的生活，不只作为被你救下的人存在。", "trait": "restraint"}]}, {"title": "安家的第一笔账", "body": "你将领回的赏钱拿出，哥哥先要推回，说自己还能卖饼。你知道若只用以后都由我养你，便又会把关心说成抹去他本事的话。你们把房屋、买卖、旧债和日常一项项算过，才发现安稳不是一大袋银子就自然长出来，也得学会让彼此愿意在一张桌上商量。", "spoken": "武大：你留些自用，别又为了面子全送出去。", "choices": [{"text": "把共同用钱与各自盘缠分清", "after": "兄弟亲近，也仍可有不必每次开口求另一人的余地。", "trait": "insight"}, {"text": "先修会漏雨的地方", "after": "你让一份胜利落成下雨时也能好睡的屋，不只摆在柜里供人称赞。", "trait": "care"}, {"text": "留一份给旧友急难", "after": "安家不是从此不问旁人，而是不再只有冒死才算相帮的办法。", "trait": "oath"}]}], "43": [{"title": "门前又一声招呼", "body": "故友来时，哥哥先从声音认人。你看见林冲自己跨过门槛，鲁智深提着朴实的礼物，施恩在后头替人拎包袱。没有谁的空位须用一碗酒代替，也不必因为见到了人就立刻再谈下一场仗。你们笑着让座，话说得重叠而无次序，这一场不齐整的团聚，比任何排得整整齐齐的阵列都使你心安。", "spoken": "鲁智深：有凳子便成，莫整那些讲究。", "choices": [{"text": "先给最晚来的人留一碗热的", "after": "你记得归舟上等过谁，家里的席位也不因到得慢就没有了。", "trait": "care"}, {"text": "请哥哥也同席坐下", "after": "这场归来不只属于会打的英雄，撑起这个家的人同样该在席间。", "trait": "mercy"}, {"text": "把藏了很久的笑话讲完", "after": "你们不必再把相见都说得沉重，也能凭活着的琐事记住彼此。", "trait": "trust"}]}, {"title": "不必再谢一次命", "body": "吃到一半，有人又要为旧日相救敬酒。你当然记得那些生死，却也不愿每回相聚都只剩一张欠命的账。朋友可以为你从险处跑一程，也可以只是后来帮你扶一下蒸笼。你想让他们知道，自己珍惜的不只是曾替你做过什么，更是这个人如今愿意怎样过日子。", "spoken": "你说：往后多来坐，便算把情分还上了。", "choices": [{"text": "不再逼人饮尽一碗", "after": "你不让感激也变成新的为难，好意可以留着慢慢过。", "trait": "restraint"}, {"text": "问起朋友各自安居的近况", "after": "他们不只在你的故事里有位置，也有属于自己的日常。", "trait": "care"}, {"text": "约定将照应传给更需要的人", "after": "恩情不必永远在几个人之间加重，也可以向外长出新的善意。", "trait": "oath"}]}, {"title": "笑声里没有军令", "body": "院外有人围着看热闹，听说几位梁山好汉在此，还以为要论武。他们等了许久，只听见谁家的菜咸、哪段路的桥补好了。你知道不是人人都愿意看这样的英雄故事，却也终于不再需要用一场险事满足他们。你们不是变得没有本领，只是本领终于可以安静地放在日子里，不必时刻叫旁人听见。", "spoken": "林冲：今日不演武，待孩子们学时再来。", "choices": [{"text": "向围观者说明只是一场相聚", "after": "你不将平静视作对名声的亏欠，也不借旧威风排挤街坊。", "trait": "restraint"}, {"text": "请愿意帮忙的人一起添桌", "after": "热闹可以不以畏惧开始，熟悉的街渐渐接纳这些不再带兵的人。", "trait": "trust"}, {"text": "记住眼前这副平常景象", "after": "往后再有不甘涌来，你至少知道自己真正想留住的是什么。", "trait": "care"}]}], "44": [{"title": "带来的旧案消息", "body": "旧案的后续由可靠人传来，与你当初留下的证言和凭据能一项项对上。主谋失了庇护，再不能用一份体面称呼让证人改口；潘金莲也已为谋害付出代价。你听得心中一松，却没有想象中还要不断追问每个仇人今后怎样受苦。哥哥正在修蒸笼，等你扶住一根木条，眼前的需要反而更实。", "spoken": "武大：旧事有个了结，便回来帮我一下。", "choices": [{"text": "确认再无牵连哥哥的追索", "after": "你将公道的最后一层落实在活人的安稳，而不只是一句解气。", "trait": "care"}, {"text": "把能证明案情的材料保存", "after": "你不靠流言维持这份清白，日后仍有可对照的凭据。", "trait": "insight"}, {"text": "听完便不再追问更残酷的细节", "after": "报应已到，你不愿将仇人的下场占满自己的余生。", "trait": "restraint"}]}, {"title": "报应与自己的日子", "body": "街坊想让你再讲一遍潘金莲怎样落到青楼，你明白他们也为哥哥的遭遇不平。但若每次聚在一起都以恶人的结局取乐，哥哥便仍会被逼着反复活在受害的那一天。你可以承认这报应来得痛快，也可以决定从此谈起这个家时，更愿让人记住炊饼、团聚与平安，而不是只记住一场谋害。", "spoken": "心声：恶人得报，不等于哥哥往后只能被这样谈起。", "choices": [{"text": "将话题还给哥哥自己的生活", "after": "他不必每回露面都解释旧案，终于能只做眼前这门生意。", "trait": "care"}, {"text": "明说不容再以旧事羞辱家人", "after": "你为已经了结的公道守住界限，不让闲话继续伤人。", "trait": "restraint"}, {"text": "感谢当初肯作证的街坊", "after": "你将注意力也留给勇敢帮过人的人，不只留给被惩罚的名字。", "trait": "oath"}]}, {"title": "不再赶路的傍晚", "body": "傍晚收摊，哥哥数钱，你帮着擦案。没有追兵、密信，也没有必须连夜走完的山道。日子安静得使你有一点不习惯，甚至会本能地去听远处是不是有人叫阵。你没有责怪自己还不能马上安稳，只将这一点警醒慢慢放回本该存在的位置：用来照看门户，不再用来催自己离开每一处已经安全的家。", "spoken": "武大：明日早些起，街角那家订了饼。", "choices": [{"text": "答应一件明日能做到的小事", "after": "你将未来从远大的承诺收回到一个能够准时开门的清早。", "trait": "care"}, {"text": "将刀挂好，不放在饭桌旁", "after": "你为日常腾出一点不必处处有兵器在场的地方。", "trait": "restraint"}, {"text": "写信告诉故友旧案已了", "after": "你不让关心你的人始终为一桩已经过去的仇悬心。", "trait": "oath"}]}], "45": [{"title": "封赏终于变小了", "body": "官牒送来时，包裹并不比一担炊饼重。你看着上头的字，想到一路有多少人只因同样几笔便能改变别人的命运。如今该领的领了，该交的也交了，最重要的反而是它不再能随意叫你离家赴险。功成不是永远多得一点，身退也不是两手空空地被人赶走；你终于同时握住了应得与不必再求的两部分。", "spoken": "你说：收好便是，明日还照常过。", "choices": [{"text": "把归凭妥存而不摆作威势", "after": "你让它用来保护生活，不用来叫街坊再多敬你一层。", "trait": "restraint"}, {"text": "留清旧部需要求援的凭据", "after": "你既已安家，仍愿意帮不能自行面对官门的人说清事。", "trait": "duty"}, {"text": "与哥哥商量赏银如何长久用", "after": "你让封赏进入真实生活，而不只留作一次热闹。", "trait": "care"}]}, {"title": "宋江的回信", "body": "宋江说诸事已交接，身边旧人也各有去处。他没有写自己从此全然无憾，只说近来睡得比从前安稳。你读见这句，觉得够了：救一个人不必等于替他将人生所有心结解尽。你们仍可能有不同看法，却不再需要拿一条更险的路证明自己当初的选择无错。你提笔回信时，先写这里有饭，有住处，来时不必另带礼。", "spoken": "宋江信中说：二郎当日的话，我如今又懂一层。", "choices": [{"text": "请他有空来坐", "after": "你不只在险时需要旧友，也愿意在无事时好好相见。", "trait": "oath"}, {"text": "不再追问谁当初更有远见", "after": "你珍惜的是人仍在，不是自己终于赢了一场道理。", "trait": "restraint"}, {"text": "把可继续互助的事写清", "after": "散去军伍以后，仍可用更平常的方式帮人过难关。", "trait": "duty"}]}, {"title": "一份不带官印的约定", "body": "旧卒来求教拳，说不愿再跟军，却怕回乡仍受欺负。你想到自己刚出场时那种只有拳头可以仗的局促，也想到后来拳头又怎样容易被别人借去。你愿教，却得先想清楚：若学生只学会使人怕，便又把自己的一条旧路分给了更多人。你同林冲商议，将护身与守界限放在同一堂课里。", "spoken": "林冲：先教站稳，再教出手，最后教收住。", "choices": [{"text": "收下想护家的人", "after": "你不以豪言与财势挑学生，先看他愿不愿对自己的本事负责。", "trait": "care"}, {"text": "写明不得恃强欺弱", "after": "旧日的教训终于成了往后能护人的规矩，而不只是一段传奇。", "trait": "duty"}, {"text": "不许拿师父名声替自己索账", "after": "你从一开始便堵住这条曾差点将自己变成新门神的路。", "trait": "restraint"}]}], "46": [{"title": "开门的第一堂课", "body": "拳坊第一日，有人盼你演打虎，有人想立刻学会最狠的一招。你请他们先把脚放稳，众人有些失望。你没有恼，也不急着讲自己从前多厉害，只让他们两两试着扶住站不稳的人。一双手可以使人倒下，也可以让人不倒；要先学哪一种，会使日后许多用本事的时刻不同。", "spoken": "你说：学拳以前，先知道旁边的人会疼。", "choices": [{"text": "把扶人与避让教在最前", "after": "你让保护不只在口号里，也进入手脚的第一个习惯。", "trait": "care"}, {"text": "解释每一个动作为何必要", "after": "学生不是只会服从师命的人，理解能使他们日后自行判断。", "trait": "duty"}, {"text": "不以逞狠者最先学会为荣耀", "after": "拳坊不再替鲁莽制造喝彩，认真与克制同样有分量。", "trait": "restraint"}]}, {"title": "哥哥送来的早餐", "body": "课还没完，哥哥挑着篮子来，学生纷纷让出道。有人想高声喊英雄之兄，哥哥摆摆手，说只是来送饼。你看见他不再畏缩，也没有借你的名字去压谁；他只把自己会做的事做得稳妥。你忽然觉得，自己苦苦争回的公道若有一个真正的样子，大约便是让他能在这里不再低头地说一句，只是送饼。", "spoken": "武大：吃完了记得把篮子带回来。", "choices": [{"text": "亲手把饼分给众人", "after": "你让学生看见尊重不只给会打的人，也给每日做饭的人。", "trait": "mercy"}, {"text": "把篮子妥放，不再当作小事", "after": "你记得过去借过的绳、欠过的饭，小承诺也值得照办。", "trait": "oath"}, {"text": "请哥哥同学生讲早起做活", "after": "你承认能教人的不只拳脚，日子里还有许多踏实本事。", "trait": "care"}]}, {"title": "不必再有一场大事", "body": "平安的日子久了，有人说你的故事少了后头的波澜。你听着并不动气。若要让传奇更好听，或许确实得再有一次大仇、一次断臂、一次惊险归来；但坐在身边的哥哥不会为此活得更好，林冲与鲁智深也不必再为旁人的热闹少一段余生。你愿意将最后的精彩留给那些愿意继续讲的人，自己只须照看明日。", "spoken": "心声：能一直无事，也可以是一种赢。", "choices": [{"text": "谢过关心，不再主动生事", "after": "你不让别人对英雄的期待重新带走刚得来的生活。", "trait": "restraint"}, {"text": "把余力用于照应街坊", "after": "本事仍有用途，只是不必每次都留下惊动全城的动静。", "trait": "care"}, {"text": "继续给故友写信", "after": "你用不传奇的往来延续当年那份真正重要的相识。", "trait": "oath"}]}], "47": [{"title": "许多年后", "body": "年岁渐长，拳坊里的学生带着孩子再来。哥哥坐在门边，常嫌你教得太晚，该吃饭时还不肯停；旧友的信有时隔得久，却总能到。你知道人生终会有人先行，却不再像军中那样一封战报便少一桌熟悉的脸。你们有过争执，也有过分离，更多的是各自完整活过了许多原来不敢想的普通年份。", "spoken": "学生：师父从前，真是一个人打了虎？", "choices": [{"text": "讲清也曾有人扶你下山", "after": "你不让后辈只记得孤勇，忘记英雄也靠别人的照应走回人间。", "trait": "care"}, {"text": "将故事讲到收刀为止", "after": "你让后来者知道，结尾不是一定要再赢一场，能够停下也很重要。", "trait": "restraint"}, {"text": "记下当年愿意帮助的人", "after": "那些没有威名的人，仍在你这一生里留下清楚的位置。", "trait": "oath"}]}, {"title": "院里最后一盏灯", "body": "夜里收门时，你仍习惯看一眼路口，却已不再期待有谁来催出征。你将戒刀收好，听见哥哥在屋里讲明日的采买。曾经以为最难的事都是与人相争，如今却知道让这一盏灯安稳照许多年，同样需要许多没有人喝彩的选择。你没有失去胆气，只是终于不再让胆气替所有想要活下去的人作对。", "spoken": "心声：功成，身退，人还在。", "choices": [{"text": "回屋听哥哥说完家常", "after": "你没有将团聚只当作一个到达的瞬间，而愿意一直留在其中生活。", "trait": "care"}, {"text": "把门闩好，给朋友留信处", "after": "家有边界，也仍有愿为故人打开的一道门。", "trait": "oath"}, {"text": "安心睡下，明日照常开门", "after": "这一回，平静不是暴风雨前的一刻，而是你自己挣来的长久日常。", "trait": "restraint"}]}, {"title": "完整的余生", "body": "后来有人将你的故事改得更惊险，说行者一生从不退让。你知道自己退让过许多：给证人留安全，给朋友留选择，给伤者留时间，也给自己留一次不再上阵的机会。正是这些不似传奇的停步，使仇人的报应不再需要拿更多亲友去换。你将最后的落款留给活着的人，愿后来的故事也能有人平安走到这里。", "spoken": "终卷：你的圆满不是抹掉一切苦，而是没有让苦吞掉所有后来。", "choices": [{"text": "把这一生讲给还在的人", "after": "你们共同拥有的不是一张名册，而是真正一起过过的日子。", "trait": "care"}, {"text": "将规矩交给愿意继续护人的后辈", "after": "功成身退以后，仍有温和而坚实的东西留下。", "trait": "duty"}, {"text": "谢过来路，接住终老的平静", "after": "你不再为证明自己无悔，非要将岁月再推回刀口。", "trait": "restraint"}]}]}};